window.PSAT_DATA = {"tests": [{"id": 1, "name": "Practice Test 1", "sections": [{"id": "rw", "name": "Reading and Writing", "modules": [{"minutes": 32, "questions": [{"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Botanist Lena Varga's field notes are remarkably <span class=\"blank\">______</span>: each entry records the date, the temperature, the soil moisture, and the exact location of every plant she examined, leaving nothing to guesswork.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["concise", "improvised", "meticulous", "skeptical"], "explanation": "The colon signals that what follows explains the blank. Notes that record every detail and leave \"nothing to guesswork\" are <b>meticulous</b> (extremely careful and precise). \"Concise\" means brief, which is the opposite of recording every detail.", "type": "mc", "answer": 2, "id": "t1rw1-1"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Although the novelist's early stories were largely ignored by critics, her later work was so widely <span class=\"blank\">______</span> that she received three major literary prizes in a single year.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["translated", "acclaimed", "imitated", "disputed"], "explanation": "\"Although\" sets up a contrast with being \"ignored by critics,\" and the result is winning three prizes. Work that is widely praised is <b>acclaimed</b>. \"Disputed\" would not lead to prizes, and \"translated\" or \"imitated\" don't contrast with being ignored by critics.", "type": "mc", "answer": 1, "id": "t1rw1-2"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Many desert plants <span class=\"blank\">______</span> water loss by opening the tiny pores on their leaves only at night, when temperatures are cooler and less moisture evaporates.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["minimize", "reveal", "accelerate", "celebrate"], "explanation": "Opening pores only when less moisture evaporates is a way to keep water loss low, so the plants <b>minimize</b> it. \"Accelerate\" means the opposite.", "type": "mc", "answer": 0, "id": "t1rw1-3"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "The city council's new parking rules were meant to be temporary, but because no one ever voted to end them, they have <span class=\"blank\">______</span> for more than a decade.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["multiplied", "vanished", "improved", "persisted"], "explanation": "Rules that were never ended have continued to exist: they have <b>persisted</b>. \"Vanished\" contradicts the sentence, and nothing suggests the rules increased in number or got better.", "type": "mc", "answer": 3, "id": "t1rw1-4"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "<p>The following text is from an original short story.</p><p>Every morning, Mr. Okafor unlocked the bakery an hour before anyone else arrived. <u>He did not need the extra time; the dough had been rising all night, and the ovens heated themselves on a timer.</u> Still, he liked to walk the empty aisles, straighten the jars of jam, and listen to the building wake up around him.</p>", "stem": "Which choice best describes the function of the underlined sentence in the text as a whole?", "choices": ["It reveals that Mr. Okafor is frustrated with the bakery's outdated equipment.", "It establishes that Mr. Okafor's early arrival isn't required by his work, which suggests that he comes early for personal reasons.", "It explains why the bakery has become more popular over time.", "It introduces a conflict between Mr. Okafor and the other employees."], "explanation": "The underlined sentence says the work doesn't require him to be early. The next sentence, starting with \"Still,\" gives his real reason: he enjoys the quiet routine. Nothing in the text mentions frustration, conflict, or popularity.", "type": "mc", "answer": 1, "id": "t1rw1-5"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "For decades, many scientists assumed that octopuses, which live only a year or two and spend most of their lives alone, had little reason to develop advanced problem-solving abilities. Yet laboratory studies have repeatedly shown octopuses unscrewing jar lids, finding their way through mazes, and even recognizing individual human caretakers. These findings have pushed researchers to reconsider which conditions lead to the evolution of intelligence.", "stem": "Which choice best states the main purpose of the text?", "choices": ["To explain why octopuses have such short life spans", "To argue that octopuses are more intelligent than any other animal", "To present findings that challenged an assumption about which kinds of animals develop intelligence", "To describe the methods researchers use to build mazes for animals"], "explanation": "The text states an assumption (\"many scientists assumed…\"), presents evidence against it (\"Yet laboratory studies…\"), and notes that researchers are reconsidering. It never compares octopuses to all other animals, and mazes and life span are only details.", "type": "mc", "answer": 2, "id": "t1rw1-6"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "Civil engineer Dana Ruiz noticed that some sidewalks in her city cracked after only a few winters while others lasted for decades. Comparing records for 300 sidewalk sections, she found that those built over clay-rich soil cracked most often. Ruiz proposed that because clay holds water, the soil beneath those sidewalks expands more when that water freezes. She then built test slabs over clay and sandy soils and froze them repeatedly in a laboratory chamber; the slabs over clay cracked first.", "stem": "Which choice best describes the overall structure of the text?", "choices": ["It compares two competing theories and then rejects both of them.", "It describes an observation, presents an explanation for it, and then reports a test that supports the explanation.", "It describes a problem and then explains why one proposed solution failed.", "It presents a claim and then lists several objections to that claim."], "explanation": "Observation (some sidewalks crack sooner, especially over clay) → explanation (clay holds water that expands when it freezes) → test (lab slabs over clay cracked first). No solution, competing theories, or objections are discussed.", "type": "mc", "answer": 1, "id": "t1rw1-7"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "<p><b>Text 1</b><br>Many historians credit the printing press with rapidly spreading new scientific ideas in fifteenth- and sixteenth-century Europe. Because printed books were far cheaper than handwritten ones, the argument goes, scholars across the continent could quickly read and respond to one another's work.</p><p><b>Text 2</b><br>Historian Marta Feld agrees that printing lowered the cost of books but cautions against assuming that cheaper books alone spread ideas. In her study of one region's archives, she found that most printed scientific works sold only a few hundred copies and that letters exchanged among scholars often reached readers months before the printed versions did.</p>", "stem": "Based on the texts, how would Feld (Text 2) most likely respond to the argument presented in Text 1?", "choices": ["She would argue that printed books were actually more expensive than handwritten ones.", "She would claim that scholars of the period rarely responded to one another's work.", "She would reject the idea that the printing press had any effect on the price of books.", "She would agree that printing made books cheaper but argue that other forms of communication also played an important role in spreading ideas."], "explanation": "Feld \"agrees that printing lowered the cost of books\" (so choices A and C are wrong), but her finding that letters reached readers first shows she thinks other communication mattered too. She never says scholars didn't respond to one another.", "type": "mc", "answer": 3, "id": "t1rw1-8"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Central Ideas and Details", "passage": "<p>The following text is from an original short story.</p><p>When Ada Moreno moved to the coast, she expected to miss the mountains where she had grown up. Instead, she found herself comparing the two constantly: the waves reminded her of wind moving through pines, and the long gray horizon felt as steady as the ridgeline she had watched from her childhood window. Slowly, the new landscape began to feel less like a replacement and more like a continuation.</p>", "stem": "Which choice best states the main idea of the text?", "choices": ["Ada comes to see her new home as connected to, rather than completely different from, the place where she grew up.", "Ada has trouble adjusting to the weather in her new home.", "Ada regrets leaving the mountains and plans to move back.", "Ada prefers the coast because it is more exciting than the mountains."], "explanation": "Ada keeps finding similarities between the coast and the mountains, and the last sentence says the coast feels like \"a continuation.\" The text never mentions regret, excitement, or the weather as a problem.", "type": "mc", "answer": 0, "id": "t1rw1-9"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Central Ideas and Details", "passage": "Researchers at a wildlife center studied how young sea otters learn to use rocks to crack open shellfish. They found that pups that spent more time near their mothers during feeding began using tools several weeks earlier than pups that spent less time near their mothers. However, all of the pups in the study had learned to use tools by the age of six months.", "stem": "According to the text, what is true about the pups that spent less time near their mothers?", "choices": ["They began using tools later than the other pups but still learned to use tools by six months of age.", "They learned to use different kinds of tools than the other pups did.", "They never learned to use tools.", "They began using tools several weeks earlier than the other pups."], "explanation": "The pups with more time near their mothers started \"several weeks earlier,\" so the other pups started later, but \"all of the pups\" had learned by six months.", "type": "mc", "answer": 0, "id": "t1rw1-10"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Textual", "passage": "Ecologist Priya Nair hypothesizes that birds of a certain species living in cities sing at a higher pitch than birds of the same species living in the countryside because higher-pitched songs are easier to hear over low-pitched traffic noise.", "stem": "Which finding, if true, would most directly support Nair's hypothesis?", "choices": ["City birds of the species sang at a higher pitch on busy weekdays than on quiet holidays when there was much less traffic.", "Countryside birds of the species sing more often in the morning than in the evening.", "Traffic noise in cities is loudest during the summer months.", "City birds of the species tend to be slightly larger than countryside birds of the species."], "explanation": "If the same city birds raise their pitch when traffic is heavy and lower it when traffic is light, that directly links pitch to traffic noise. The other findings don't connect song pitch to noise.", "type": "mc", "answer": 0, "id": "t1rw1-11"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Textual", "passage": "In the original short story \"The Lantern Keeper,\" the narrator describes her grandfather as an extremely patient man.", "stem": "Which quotation from the story most effectively illustrates the narrator's claim?", "choices": ["\"On Sundays he wore a blue wool coat that smelled of cedar.\"", "\"He would wait an entire afternoon for a heron to step close enough to sketch, never once complaining about the cold.\"", "\"His workshop was crowded with half-finished clocks and boxes of brass gears.\"", "\"He told me that the lighthouse had been built by his own grandfather.\""], "explanation": "Waiting all afternoon without complaining is a clear example of patience. The other quotations describe his workshop, family history, and clothing, not patience.", "type": "mc", "answer": 1, "id": "t1rw1-12"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Quantitative", "passage": "<p>A student studying soil health compared fields where farmers planted cover crops (plants grown between harvests to protect the soil) with fields where they did not. The student concluded that planting cover crops increased the amount of organic matter in the soil over time.</p><table class=\"data\"><caption>Average soil organic matter (percent of soil)</caption><tr><th>Field type</th><th>Year 1</th><th>Year 3</th><th>Year 5</th></tr><tr><td>Cover crops</td><td>2.1%</td><td>2.6%</td><td>3.0%</td></tr><tr><td>No cover crops</td><td>2.1%</td><td>2.1%</td><td>2.0%</td></tr></table>", "stem": "Which choice most effectively uses data from the table to support the student's conclusion?", "choices": ["In year 1, fields with cover crops and fields without cover crops both had 2.1% organic matter.", "In fields without cover crops, organic matter was 2.0% in year 5.", "In fields with cover crops, organic matter rose from 2.1% in year 1 to 3.0% in year 5, while in fields without cover crops it stayed at about 2.1%.", "In fields with cover crops, organic matter was 2.6% in year 3."], "explanation": "To show cover crops increased organic matter <i>over time</i>, you need the change in cover-crop fields compared with fields without them. Only choice C gives both the increase (2.1% → 3.0%) and the comparison.", "type": "mc", "answer": 2, "id": "t1rw1-13"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Inferences", "passage": "Archaeologists excavating an ancient inland settlement found large quantities of fish bones but very few fishing tools such as hooks, spears, or nets. The settlement was located more than 100 kilometers from the nearest coast or large lake, and geological evidence shows that the surrounding landscape has changed little since the settlement was occupied. These findings suggest that <span class=\"blank\">______</span>", "stem": "Which choice most logically completes the text?", "choices": ["the settlement's residents likely obtained fish through trade with other communities.", "the settlement was once located on a coast.", "the settlement's residents caught fish in a nearby lake using hooks and nets.", "the settlement's residents did not eat fish."], "explanation": "Residents had lots of fish but few fishing tools and no nearby water, and the landscape hasn't changed. The most logical explanation is that the fish came from elsewhere, through trade. The other choices contradict details in the text.", "type": "mc", "answer": 0, "id": "t1rw1-14"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Inferences", "passage": "Some critics have argued that the painter Tomas Lind began using bright colors only after he moved to a sunny coastal town in 1925. However, a recently rediscovered set of Lind's paintings dated to 1921, when he still lived in a gray northern city, features the same vivid oranges and blues found in his later work. This discovery suggests that <span class=\"blank\">______</span>", "stem": "Which choice most logically completes the text?", "choices": ["Lind painted only while he lived in the northern city.", "critics have misdated the paintings Lind made after 1925.", "Lind stopped using bright colors after he moved in 1925.", "Lind's use of bright colors was not simply a result of his move to the coastal town."], "explanation": "If Lind already used vivid colors in 1921, before the move, the move can't be the only reason for his bright palette. Nothing suggests he stopped painting, stopped using bright colors, or that later works were misdated.", "type": "mc", "answer": 3, "id": "t1rw1-15"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "Biologist Rosa Iglesias studies the migration of monarch <span class=\"blank\">______</span> which can travel up to 3,000 miles each year.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["butterflies.", "butterflies:", "butterflies;", "butterflies,"], "explanation": "\"Which can travel…\" is a nonessential clause describing the butterflies, so it is set off with a comma. A semicolon or period would leave \"which can travel…\" as a fragment, and a colon isn't used before a \"which\" clause.", "type": "mc", "answer": 3, "id": "t1rw1-16"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "The town's first public library opened in <span class=\"blank\">______</span> within a year, more than half of the town's residents had borrowed at least one book.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["1897", "1897,", "1897 which", "1897;"], "explanation": "Both parts are independent clauses. A semicolon can join them. A comma alone creates a comma splice, no punctuation creates a run-on, and \"which\" makes the sentence ungrammatical.", "type": "mc", "answer": 3, "id": "t1rw1-17"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "The museum's new exhibit features three kinds of ancient <span class=\"blank\">______</span> tools, pottery, and jewelry.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["artifacts that", "artifacts, and", "artifacts;", "artifacts:"], "explanation": "A colon introduces a list that explains what came before it. A semicolon must join two independent clauses, and \"tools, pottery, and jewelry\" isn't one.", "type": "mc", "answer": 3, "id": "t1rw1-18"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "The bridge's designer—a young engineer named Clara <span class=\"blank\">______</span> won the city's competition with a plan that used half as much steel as her rivals' proposals.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["Holt,", "Holt", "Holt—", "Holt;"], "explanation": "The phrase \"a young engineer named Clara Holt\" opens with a dash, so it must close with a dash. Mixing a dash with a comma is incorrect.", "type": "mc", "answer": 2, "id": "t1rw1-19"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "The collection of letters, which a historian discovered in an old trunk, <span class=\"blank\">______</span> new details about daily life in the colony.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["have revealed", "reveals", "are revealing", "reveal"], "explanation": "The subject is the singular noun \"collection\" (not \"letters,\" which is inside a prepositional phrase), so it needs the singular verb \"reveals.\"", "type": "mc", "answer": 1, "id": "t1rw1-20"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "Last summer, the research team <span class=\"blank\">______</span> more than 200 water samples from the river before analyzing them in the lab.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["will collect", "collects", "collected", "is collecting"], "explanation": "\"Last summer\" places the action in the past, so the past tense \"collected\" is correct.", "type": "mc", "answer": 2, "id": "t1rw1-21"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "After months of debate, the school committee finally announced <span class=\"blank\">______</span> decision about the new schedule.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["it's", "they're", "its", "their"], "explanation": "\"Committee\" is a singular noun, so it takes the singular possessive \"its.\" \"It's\" means \"it is,\" and \"their\"/\"they're\" are plural.", "type": "mc", "answer": 2, "id": "t1rw1-22"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "Honeybees share the location of food with one another through a movement called the waggle dance. <span class=\"blank\">______</span> the angle of the dance indicates the direction of the food relative to the sun.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["Specifically,", "Nevertheless,", "In contrast,", "However,"], "explanation": "The second sentence gives a specific detail about how the dance communicates location, so \"Specifically\" fits. Nothing contrasts with the first sentence.", "type": "mc", "answer": 0, "id": "t1rw1-23"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "The town's population grew rapidly in the 1950s as new factories opened. <span class=\"blank\">______</span> when the factories closed in the 1980s, many residents moved away.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["Similarly,", "Later,", "In addition,", "For example,"], "explanation": "The second sentence describes what happened afterward, decades later, so \"Later\" is logical. Moving away isn't similar to or an example of population growth.", "type": "mc", "answer": 1, "id": "t1rw1-24"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "Solar panels produce no emissions while they generate electricity. <span class=\"blank\">______</span> manufacturing them requires energy and raw materials, so they are not entirely free of environmental impact.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["Likewise,", "Therefore,", "For instance,", "However,"], "explanation": "The second sentence qualifies the first: panels don't pollute while running, but making them has costs. That contrast calls for \"However.\"", "type": "mc", "answer": 3, "id": "t1rw1-25"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "<p>While researching a topic, a student has taken the following notes:</p><ul><li>Maple Street Community Garden opened in 2015.</li><li>It has 40 garden plots.</li><li>Northside Community Garden opened in 2019.</li><li>It has 65 garden plots.</li><li>Both gardens donate produce to local food banks.</li></ul>", "stem": "The student wants to emphasize a difference in size between the two gardens. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Maple Street Community Garden has 40 plots, while Northside Community Garden, which opened four years later, has 65.", "Maple Street Community Garden opened in 2015.", "Both Maple Street and Northside Community Gardens donate produce to local food banks.", "Northside Community Garden opened in 2019 and donates produce to local food banks."], "explanation": "Size is shown by the number of plots. Only choice A compares 40 plots with 65 plots. The others mention a similarity or only one garden.", "type": "mc", "answer": 0, "id": "t1rw1-26"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "<p>While researching a topic, a student has taken the following notes:</p><ul><li>A food desert is an area where residents have limited access to affordable, nutritious food.</li><li>Researchers in one city identified 12 neighborhoods that met this definition.</li><li>Residents of those neighborhoods lived an average of 2.5 miles from a full-service grocery store.</li><li>The city has since opened three new grocery stores in those neighborhoods.</li></ul>", "stem": "The student wants to introduce the concept of a food desert to an audience unfamiliar with it. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Residents of 12 neighborhoods in one city lived an average of 2.5 miles from a full-service grocery store.", "Food deserts, areas where residents have limited access to affordable, nutritious food, were identified in 12 neighborhoods of one city.", "One city has opened three new grocery stores in neighborhoods that were identified as food deserts.", "Researchers in one city found 12 neighborhoods that met the definition of a food desert."], "explanation": "An audience unfamiliar with the term needs a definition. Only choice B explains what a food desert is. Choice D uses the term without defining it.", "type": "mc", "answer": 1, "id": "t1rw1-27"}]}, {"minutes": 32, "questions": [{"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "The scientist's conclusions were <span class=\"blank\">______</span>: she acknowledged that her sample was small and that further studies might produce different results.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["inaccessible", "tentative", "unoriginal", "definitive"], "explanation": "Admitting that the sample was small and that results might change shows her conclusions were not final: they were <b>tentative</b>. \"Definitive\" means the opposite.", "type": "mc", "answer": 1, "id": "t1rw2-1"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "In her review, the critic praised the film's <span class=\"blank\">______</span> dialogue, noting that the characters rarely used two words when one would do.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["ornate", "melodramatic", "rambling", "terse"], "explanation": "Dialogue that never uses two words where one will do is short and to the point: <b>terse</b>. \"Ornate\" and \"rambling\" suggest the opposite.", "type": "mc", "answer": 3, "id": "t1rw2-2"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Although two species of tree frog look nearly identical, their mating calls are <span class=\"blank\">______</span>, allowing females to easily recognize males of their own species.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["distinct", "faint", "infrequent", "similar"], "explanation": "\"Although\" contrasts the frogs' similar looks with their calls, and females can \"easily recognize\" their own species. So the calls must be clearly different: <b>distinct</b>.", "type": "mc", "answer": 0, "id": "t1rw2-3"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Engineers installed a series of gates along the river to <u>check</u> the flow of floodwater during heavy storms, protecting the farms downstream.", "stem": "As used in the text, what does the word \"check\" most nearly mean?", "choices": ["mark", "restrain", "verify", "examine"], "explanation": "Gates that protect farms from floodwater hold back the water. Here, \"check\" means <b>restrain</b>. The more common meanings (examine, verify) don't fit gates controlling water.", "type": "mc", "answer": 1, "id": "t1rw2-4"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "<p>The following text is from an original short story.</p><p>Grandmother's kitchen had no clock. Meals happened when the bread was ready, when the light through the window turned gold, when someone's stomach rumbled loudly enough to be heard across the table. I used to find this maddening. <u>Now, years later, I cannot hear a kitchen timer without thinking of everything that room taught me about paying attention.</u></p>", "stem": "Which choice best describes the function of the underlined sentence in the text as a whole?", "choices": ["It introduces a new character who will become important later.", "It explains why the narrator's grandmother chose not to own a clock.", "It reveals that the narrator's attitude toward the kitchen's lack of a clock has changed over time.", "It describes a specific meal that the narrator remembers clearly."], "explanation": "\"I used to find this maddening\" is the narrator's past view. \"Now, years later,\" the narrator appreciates what the room taught. The underlined sentence shows that shift in attitude.", "type": "mc", "answer": 2, "id": "t1rw2-5"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "Many people assume that the Sahara has always been a desert. In fact, evidence from ancient lake sediments, along with rock art depicting giraffes and herds of cattle, shows that roughly 10,000 to 5,000 years ago much of the region was covered in grassland and dotted with lakes. Scientists think that gradual shifts in Earth's orbit, which altered seasonal rainfall patterns, eventually caused the region to dry out.", "stem": "Which choice best states the main purpose of the text?", "choices": ["To compare the Sahara with other deserts around the world", "To correct a common misconception about the history of a region", "To argue that the Sahara will soon become grassland again", "To describe the techniques ancient artists used to create rock art"], "explanation": "The text opens with what \"many people assume\" and then says \"In fact…\" to show that assumption is wrong. It makes no prediction, says nothing about art techniques, and mentions no other deserts.", "type": "mc", "answer": 1, "id": "t1rw2-6"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "Some plants can \"warn\" their neighbors about insect attacks. When caterpillars chew the leaves of a sagebrush plant, the plant releases chemicals into the air. <u>Nearby plants that detect these chemicals begin producing compounds that make their own leaves less appealing to insects.</u> Researchers think this response may help a whole patch of plants resist an outbreak of hungry caterpillars.", "stem": "Which choice best describes the function of the underlined sentence in the text as a whole?", "choices": ["It presents an objection to the researchers' main idea.", "It explains why caterpillars prefer sagebrush to other plants.", "It describes how neighboring plants respond to the chemical signal mentioned in the previous sentence.", "It describes how researchers first discovered sagebrush plants."], "explanation": "The previous sentence says the plant releases chemicals; the underlined sentence tells what neighboring plants do when they detect them. That explains how the \"warning\" works.", "type": "mc", "answer": 2, "id": "t1rw2-7"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "<p><b>Text 1</b><br>Many nutrition experts recommend eating breakfast every day, pointing to studies showing that people who regularly eat breakfast tend to weigh less than people who skip it.</p><p><b>Text 2</b><br>Researcher Joon Park notes that most of those studies are observational: they record what people already do rather than assigning people to eat or skip breakfast. When Park reviewed experiments that randomly assigned participants to one group or the other, he found little difference in weight. People who eat breakfast, Park suggests, may simply differ from others in their other habits.</p>", "stem": "Based on the texts, how would Park (Text 2) most likely respond to the experts' reasoning in Text 1?", "choices": ["He would claim that people who skip breakfast weigh less than people who eat it.", "He would argue that observational studies always produce false results.", "He would agree that eating breakfast causes people to lose weight.", "He would argue that the studies they cite show a link between breakfast and weight but don't show that eating breakfast causes lower weight."], "explanation": "Park's point is that observational studies show a correlation but can't prove cause, and the randomized experiments found little difference. He doesn't say observational studies are \"always\" false; that choice goes too far.", "type": "mc", "answer": 3, "id": "t1rw2-8"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Central Ideas and Details", "passage": "<p>The following text is from an original short story.</p><p>Inez had practiced the cello piece for months, but on the night of the recital her hands would not stop shaking. She stared at the first note on the page as though it were written in a language she had never learned. Then, from the third row, she heard her younger brother cough twice—the signal they had agreed on weeks earlier, which meant <i>you've got this</i>. She lifted her bow.</p>", "stem": "Which choice best states the main idea of the text?", "choices": ["Inez's brother is ill, and his coughing disrupts the recital.", "Inez has forgotten how to read music and cannot perform.", "Although Inez is nervous before her performance, a signal of support from her brother steadies her.", "Inez decides that she is not ready to perform and leaves the stage."], "explanation": "Inez is shaking with nerves, hears the agreed-upon signal, and \"lifted her bow,\" meaning she is ready to play. The cough is a planned signal, not illness, and she doesn't leave.", "type": "mc", "answer": 2, "id": "t1rw2-9"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Central Ideas and Details", "passage": "Researchers studying a population of lizards on a small Caribbean island measured the animals shortly before a major hurricane struck. When they returned after the storm, they found that the surviving lizards had, on average, larger toe pads and longer front legs than the population had before the storm. The researchers suggest that these traits helped lizards cling to branches during the hurricane's powerful winds.", "stem": "According to the text, why do the researchers think the surviving lizards had larger toe pads on average?", "choices": ["The storm carried lizards with larger toe pads from other islands.", "The lizards' toe pads grew larger in response to the storm.", "Larger toe pads help lizards catch insects after storms.", "Larger toe pads likely helped lizards hold on to branches during strong winds."], "explanation": "The last sentence gives the researchers' explanation: the traits helped lizards cling to branches in the wind, so lizards with them were more likely to survive.", "type": "mc", "answer": 3, "id": "t1rw2-10"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Textual", "passage": "Economist Sara Lindqvist claims that when a city opens a new public library branch, small businesses located near the branch benefit from increased foot traffic.", "stem": "Which finding, if true, would most directly support Lindqvist's claim?", "choices": ["Shops within a few blocks of newly opened library branches reported a larger increase in customers in the following year than similar shops located farther away did.", "Most visitors to public libraries are students under the age of 18.", "Public libraries tend to lend more books during the winter than during the summer.", "Cities that build new library branches often build new parks at the same time."], "explanation": "The claim is about businesses <i>near</i> new branches gaining customers. Comparing nearby shops with similar shops farther away isolates the effect of the library.", "type": "mc", "answer": 0, "id": "t1rw2-11"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Textual", "passage": "A team of researchers hypothesizes that females of a certain beetle species choose where to lay their eggs based on soil temperature, preferring warmer soil.", "stem": "Which finding, if true, would most directly weaken the researchers' hypothesis?", "choices": ["Beetle larvae of the species grow faster in warm soil than in cool soil.", "When offered patches of soil at several different temperatures, the beetles laid the most eggs in the warmest soil.", "Adult beetles of the species are most active during the summer.", "When offered patches of soil at several different temperatures, the beetles laid eggs equally often in warm and cool soil."], "explanation": "If beetles show no preference between warm and cool soil, temperature isn't guiding their choice, which directly weakens the hypothesis. Choice B would <i>support</i> it.", "type": "mc", "answer": 3, "id": "t1rw2-12"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Quantitative", "passage": "<p>A student is researching public transit use in three cities and claims that among the three cities, City A saw the largest increase in weekly transit use between 2010 and 2020.</p><table class=\"data\"><caption>Percent of residents who used public transit at least once a week</caption><tr><th>City</th><th>2010</th><th>2020</th></tr><tr><td>City A</td><td>22%</td><td>31%</td></tr><tr><td>City B</td><td>35%</td><td>33%</td></tr><tr><td>City C</td><td>18%</td><td>19%</td></tr></table>", "stem": "Which choice most effectively uses data from the table to support the student's claim?", "choices": ["City B had the highest rate of weekly transit use in 2010.", "In City A, weekly transit use rose from 22% to 31%, an increase of 9 percentage points, compared with an increase of 1 point in City C and a decrease in City B.", "In 2020, the rate of weekly transit use in City B (33%) was higher than the rate in City A (31%).", "City C had the lowest rate of weekly transit use in both 2010 and 2020."], "explanation": "To show City A had the <i>largest increase</i>, you must compare the changes in all three cities. Only choice B does that. Choice C is about levels, not changes, and makes City A look weaker.", "type": "mc", "answer": 1, "id": "t1rw2-13"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Inferences", "passage": "In dry regions, trees tend to form wide growth rings in years with plenty of rain and narrow rings in years of drought. While examining a 400-year-old pine from a dry mountain valley, a researcher noticed a series of extremely narrow rings corresponding to the years 1576 to 1585. This suggests that <span class=\"blank\">______</span>", "stem": "Which choice most logically completes the text?", "choices": ["the tree was planted in 1576.", "the valley likely experienced a prolonged drought during that period.", "the valley received unusually heavy rainfall during that period.", "trees all over the world grew slowly during that period."], "explanation": "Narrow rings indicate drought years, and there was a long series of them, so a long drought is the logical conclusion. One tree in one valley can't tell us about trees \"all over the world.\"", "type": "mc", "answer": 1, "id": "t1rw2-14"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Inferences", "passage": "In a study, one group of volunteers memorized a list of words and then took a 90-minute nap, while a second group memorized the same list and then stayed awake watching a calm documentary for 90 minutes. When tested afterward, the nap group recalled significantly more words. Because both groups spent the same amount of time between memorizing and testing, the researchers concluded that <span class=\"blank\">______</span>", "stem": "Which choice most logically completes the text?", "choices": ["watching documentaries improves people's ability to remember lists.", "the awake group had memorized a different list of words.", "the difference in recall was likely related to sleep rather than to the amount of time that had passed.", "longer naps always lead to better memory than shorter naps."], "explanation": "Since time was the same for both groups, time can't explain the difference; sleep is the key difference. The study tested only one nap length, so \"always\" goes too far, and both groups had the same list.", "type": "mc", "answer": 2, "id": "t1rw2-15"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "The novel was first published in installments in a weekly <span class=\"blank\">______</span> readers had to wait seven days to find out what happened next.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["magazine so,", "magazine,", "magazine, so", "magazine: so,"], "explanation": "Two independent clauses can be joined by a comma plus a coordinating conjunction (\"so\"). A comma alone is a comma splice, and the comma belongs before \"so,\" not after it.", "type": "mc", "answer": 2, "id": "t1rw2-16"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "The trail to the summit is steep and <span class=\"blank\">______</span> it is one of the most popular hikes in the park.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["rocky nevertheless,", "rocky, nevertheless,", "rocky; nevertheless,", "rocky; nevertheless"], "explanation": "\"Nevertheless\" is a conjunctive adverb, not a conjunction. When it begins the second of two independent clauses, use a semicolon before it and a comma after it.", "type": "mc", "answer": 2, "id": "t1rw2-17"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "The students who volunteered at the animal shelter every Saturday <span class=\"blank\">______</span> a total of 600 hours of service last year.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["; contributed", ", contributed", "contributed,", "contributed"], "explanation": "The subject (\"The students who volunteered … every Saturday\") should not be separated from its verb (\"contributed\") by any punctuation.", "type": "mc", "answer": 3, "id": "t1rw2-18"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "Born in a small fishing <span class=\"blank\">______</span> the poet often wrote about the sea and the people who worked on it.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["village;", "village:", "village,", "village."], "explanation": "\"Born in a small fishing village\" is an introductory phrase, so a comma separates it from the main clause. A semicolon, period, or colon would leave the phrase as a fragment.", "type": "mc", "answer": 2, "id": "t1rw2-19"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "Each of the paintings in the gallery's new exhibit <span class=\"blank\">______</span> been carefully restored by a team of conservators.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["has", "have", "are", "were"], "explanation": "The subject is \"Each,\" which is singular, so the verb must be the singular \"has.\" \"Of the paintings\" is a prepositional phrase that doesn't change the subject.", "type": "mc", "answer": 0, "id": "t1rw2-20"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "The <span class=\"blank\">______</span> nests, each one built by a different pair of birds, cling to the underside of the old stone bridge.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["swallows'", "swallow's", "swallows", "swallows's"], "explanation": "The nests belong to many birds (\"a different pair of birds\"), so use the plural possessive \"swallows'.\" \"Swallow's\" refers to one bird, and \"swallows\" has no apostrophe to show possession.", "type": "mc", "answer": 0, "id": "t1rw2-21"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "Having finished the experiment two days ahead of schedule, <span class=\"blank\">______</span>", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["the students wrote up their results.", "the students' results were written up.", "writing up the results was the students' next step.", "the results were written up by the students."], "explanation": "The opening phrase describes whoever finished the experiment, so the words right after the comma must name them: \"the students.\" The other choices make it sound like the results finished the experiment (a dangling modifier).", "type": "mc", "answer": 0, "id": "t1rw2-22"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "Early telescopes produced blurry, rainbow-edged images because different colors of light bend by different amounts as they pass through glass lenses. <span class=\"blank\">______</span> Isaac Newton designed a telescope that used a curved mirror instead of a lens to focus light.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["Meanwhile,", "For example,", "Similarly,", "To avoid this problem,"], "explanation": "Newton's mirror telescope was a solution to the blurriness caused by lenses. \"To avoid this problem\" expresses that problem-and-solution relationship.", "type": "mc", "answer": 3, "id": "t1rw2-23"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "Most volcanoes form along the boundaries of tectonic plates, where plates collide or pull apart. <span class=\"blank\">______</span> the volcanoes of Hawaii formed far from any plate boundary, above a hot spot deep in Earth's mantle.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["Therefore,", "By contrast,", "Thus,", "Additionally,"], "explanation": "Hawaii's volcanoes are an exception to the pattern in the first sentence, so a contrasting transition is needed.", "type": "mc", "answer": 1, "id": "t1rw2-24"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "The study's authors caution that their sample included only 40 participants. <span class=\"blank\">______</span> they recommend that larger studies be conducted before the findings are applied more broadly.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["Accordingly,", "Conversely,", "Nevertheless,", "In other words,"], "explanation": "Recommending larger studies is a logical result of having a small sample. \"Accordingly\" means \"as a result of this.\"", "type": "mc", "answer": 0, "id": "t1rw2-25"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "<p>While researching a topic, a student has taken the following notes:</p><ul><li>The Atacama Desert in Chile is one of the driest places on Earth.</li><li>Some weather stations there have recorded almost no rain for years at a time.</li><li>Several major astronomical observatories have been built in the Atacama.</li><li>Astronomers value very dry air because water vapor in the atmosphere blurs observations.</li></ul>", "stem": "The student wants to explain why astronomers build observatories in the Atacama Desert. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Several major astronomical observatories are located in Chile.", "Because water vapor blurs observations and the Atacama Desert's air is so dry, astronomers have built several major observatories there.", "Some weather stations in the Atacama Desert have recorded almost no rain for years.", "The Atacama Desert in Chile is one of the driest places on Earth."], "explanation": "An explanation needs a reason. Choice B connects the dryness of the air to why astronomers value the location. The others state facts without the \"why.\"", "type": "mc", "answer": 1, "id": "t1rw2-26"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "<p>While researching a topic, a student has taken the following notes:</p><ul><li>Novelist R. Delgado's first book, <i>The Quiet Harbor</i>, was published in 2008.</li><li>It is set in a fishing town in Maine.</li><li>Delgado's second novel, <i>Salt and Iron</i>, was published in 2014.</li><li>It is also set in a fishing town in Maine.</li><li><i>The Quiet Harbor</i> is told by a single narrator; <i>Salt and Iron</i> alternates among four narrators.</li></ul>", "stem": "The student wants to emphasize a similarity between the two novels. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Both of R. Delgado's novels, <i>The Quiet Harbor</i> (2008) and <i>Salt and Iron</i> (2014), are set in a fishing town in Maine.", "R. Delgado published <i>The Quiet Harbor</i> in 2008.", "<i>The Quiet Harbor</i> is told by a single narrator, whereas <i>Salt and Iron</i> alternates among four narrators.", "<i>Salt and Iron</i> was published six years after <i>The Quiet Harbor</i>."], "explanation": "The goal is a similarity. Both novels share a setting. Choice C highlights a difference, and choice D gives a difference in dates.", "type": "mc", "answer": 0, "id": "t1rw2-27"}]}]}, {"id": "math", "name": "Math", "modules": [{"minutes": 35, "questions": [{"id": "t1m1-1", "sec": "math", "domain": "Algebra", "skill": "Linear equations in one variable", "stem": "If 3<i>x</i> + 7 = 22, what is the value of <i>x</i>?", "choices": ["3", "5", "7", "15"], "answer": 1, "explanation": "Subtract 7 from both sides: 3<i>x</i> = 15. Divide by 3: <i>x</i> = 5.", "type": "mc"}, {"id": "t1m1-2", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Ratios, rates, proportions, and units", "stem": "A recipe uses 3 cups of flour for every 2 cups of milk. At this rate, how many cups of flour are needed for 10 cups of milk?", "choices": ["12", "15", "20", "30"], "answer": 1, "explanation": "Set up a proportion: 3/2 = <i>f</i>/10, so <i>f</i> = 10 × 3/2 = 15 cups.", "type": "mc"}, {"id": "t1m1-3", "sec": "math", "domain": "Advanced Math", "skill": "Equivalent expressions", "stem": "Which expression is equivalent to (<i>x</i> + 4)(<i>x</i> − 2)?", "choices": ["<i>x</i><sup>2</sup> + 2<i>x</i> + 8", "<i>x</i><sup>2</sup> + 6<i>x</i> − 8", "<i>x</i><sup>2</sup> − 2<i>x</i> − 8", "<i>x</i><sup>2</sup> + 2<i>x</i> − 8"], "answer": 3, "explanation": "FOIL: <i>x</i>·<i>x</i> − 2<i>x</i> + 4<i>x</i> − 8 = <i>x</i><sup>2</sup> + 2<i>x</i> − 8.", "type": "mc"}, {"id": "t1m1-4", "sec": "math", "domain": "Algebra", "skill": "Linear functions", "stem": "The function <i>f</i> is defined by <i>f</i>(<i>x</i>) = 4<i>x</i> − 9. What is the value of <i>f</i>(5)?", "choices": null, "answer": "11", "explanation": "Substitute 5 for <i>x</i>: 4(5) − 9 = 20 − 9 = 11.", "type": "spr"}, {"id": "t1m1-5", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Percentages", "stem": "A jacket originally priced at $80 is on sale for 25% off. What is the sale price of the jacket?", "choices": ["$20", "$55", "$60", "$64"], "answer": 2, "explanation": "25% of $80 is $20. The sale price is $80 − $20 = $60. (Shortcut: 75% of 80 = 0.75 × 80 = 60.)", "type": "mc"}, {"id": "t1m1-6", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "stem": "Two angles are supplementary. One of the angles measures 38°. What is the measure, in degrees, of the other angle?", "choices": null, "answer": "142", "explanation": "Supplementary angles add up to 180°. 180 − 38 = 142.", "type": "spr"}, {"id": "t1m1-7", "sec": "math", "domain": "Algebra", "skill": "Linear equations in two variables", "stem": "A line in the <i>xy</i>-plane passes through the points (0, 3) and (2, 11). What is the slope of the line?", "choices": ["3", "4", "7", "8"], "answer": 1, "explanation": "Slope = (change in <i>y</i>)/(change in <i>x</i>) = (11 − 3)/(2 − 0) = 8/2 = 4.", "type": "mc"}, {"id": "t1m1-8", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear functions", "stem": "The function <i>g</i> is defined by <i>g</i>(<i>x</i>) = <i>x</i><sup>2</sup> − 5. What is the value of <i>g</i>(−3)?", "choices": ["−14", "−1", "4", "14"], "answer": 2, "explanation": "(−3)<sup>2</sup> = 9, and 9 − 5 = 4. A common mistake is computing −3<sup>2</sup> as −9, which gives −14.", "type": "mc"}, {"id": "t1m1-9", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "One-variable data", "stem": "What is the mean of the data set 4, 7, 7, 9, 13?", "choices": ["7", "8", "9", "40"], "answer": 1, "explanation": "Add the values: 4 + 7 + 7 + 9 + 13 = 40. Divide by the number of values, 5: 40/5 = 8.", "type": "mc"}, {"id": "t1m1-10", "sec": "math", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "stem": "<div class=\"eq\"><i>x</i> + <i>y</i> = 10<br><i>x</i> − <i>y</i> = 4</div>What is the value of <i>x</i> in the solution to the system of equations above?", "choices": null, "answer": "7", "explanation": "Add the two equations: 2<i>x</i> = 14, so <i>x</i> = 7. (Then <i>y</i> = 3.)", "type": "spr"}, {"id": "t1m1-11", "sec": "math", "domain": "Algebra", "skill": "Linear inequalities in one or two variables", "stem": "A phone plan costs $25 per month plus $0.10 for each text message sent. A student wants to spend at most $40 per month on the plan. Which inequality represents the number of texts, <i>t</i>, the student can send in a month?", "choices": ["0.10 + 25<i>t</i> ≤ 40", "25 + 0.10<i>t</i> ≥ 40", "25<i>t</i> + 0.10 ≥ 40", "25 + 0.10<i>t</i> ≤ 40"], "answer": 3, "explanation": "Monthly cost = 25 + 0.10<i>t</i>. \"At most $40\" means the cost is less than or equal to 40: 25 + 0.10<i>t</i> ≤ 40.", "type": "mc"}, {"id": "t1m1-12", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "stem": "If <i>x</i><sup>2</sup> − 9 = 16 and <i>x</i> &gt; 0, what is the value of <i>x</i>?", "choices": null, "answer": "5", "explanation": "Add 9 to both sides: <i>x</i><sup>2</sup> = 25, so <i>x</i> = 5 or <i>x</i> = −5. Since <i>x</i> &gt; 0, <i>x</i> = 5.", "type": "spr"}, {"id": "t1m1-13", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "stem": "A rectangle has an area of 72 square inches and a length of 12 inches. What is the perimeter, in inches, of the rectangle?", "choices": ["18", "30", "36", "60"], "answer": 2, "explanation": "Width = 72/12 = 6 inches. Perimeter = 2(12 + 6) = 36 inches.", "type": "mc"}, {"id": "t1m1-14", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Probability and conditional probability", "stem": "A bag contains 5 red marbles, 3 blue marbles, and 2 green marbles. If one marble is chosen at random, what is the probability that it is blue?", "choices": ["3/10", "1/3", "3/7", "3/5"], "answer": 0, "explanation": "There are 5 + 3 + 2 = 10 marbles, and 3 are blue, so the probability is 3/10.", "type": "mc"}, {"id": "t1m1-15", "sec": "math", "domain": "Algebra", "skill": "Linear functions", "stem": "A plumber uses the equation <i>C</i> = 15<i>h</i> + 40 to find the total charge <i>C</i>, in dollars, for a job that takes <i>h</i> hours. What is the best interpretation of 15 in this context?", "choices": ["The fixed fee the plumber charges for every job", "The charge per hour of work", "The total charge for a 1-hour job", "The number of hours the job takes"], "answer": 1, "explanation": "15 is multiplied by the number of hours, so the charge goes up $15 for each additional hour. 40 is the fixed fee charged regardless of hours.", "type": "mc"}, {"id": "t1m1-16", "sec": "math", "domain": "Advanced Math", "skill": "Equivalent expressions", "stem": "Which expression is equivalent to 6<i>x</i><sup>2</sup> + 9<i>x</i>?", "choices": ["3(2<i>x</i><sup>2</sup> + 9<i>x</i>)", "3<i>x</i>(2<i>x</i> + 3)", "6<i>x</i>(<i>x</i> + 9)", "3<i>x</i>(2<i>x</i> + 9)"], "answer": 1, "explanation": "The greatest common factor of 6<i>x</i><sup>2</sup> and 9<i>x</i> is 3<i>x</i>: 6<i>x</i><sup>2</sup> + 9<i>x</i> = 3<i>x</i>(2<i>x</i> + 3).", "type": "mc"}, {"id": "t1m1-17", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "stem": "A right triangle has legs of length 9 and 12. What is the length of the hypotenuse?", "choices": null, "answer": "15", "explanation": "By the Pythagorean theorem, <i>c</i><sup>2</sup> = 9<sup>2</sup> + 12<sup>2</sup> = 81 + 144 = 225, so <i>c</i> = 15. (This is a 3-4-5 triangle scaled by 3.)", "type": "spr"}, {"id": "t1m1-18", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear functions", "stem": "A colony of bacteria starts with 500 cells, and the number of cells doubles every 3 hours. Which function gives the number of cells, <i>P</i>(<i>t</i>), after <i>t</i> hours?", "choices": ["<i>P</i>(<i>t</i>) = 500(3)<sup><i>t</i>/2</sup>", "<i>P</i>(<i>t</i>) = 2(500)<sup><i>t</i>/3</sup>", "<i>P</i>(<i>t</i>) = 500(2)<sup><i>t</i>/3</sup>", "<i>P</i>(<i>t</i>) = 500(2)<sup>3<i>t</i></sup>"], "answer": 2, "explanation": "Start value 500; growth factor 2; it doubles once every 3 hours, so the number of doublings after <i>t</i> hours is <i>t</i>/3. <i>P</i>(<i>t</i>) = 500(2)<sup><i>t</i>/3</sup>. Check: <i>P</i>(3) = 1,000 and <i>P</i>(6) = 2,000.", "type": "mc"}, {"id": "t1m1-19", "sec": "math", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "stem": "<div class=\"eq\">2<i>x</i> + 3<i>y</i> = 12<br>4<i>x</i> + <i>ky</i> = 20</div>In the system of equations above, <i>k</i> is a constant. If the system has no solution, what is the value of <i>k</i>?", "choices": null, "answer": "6", "explanation": "A system of two linear equations has no solution when the lines are parallel: same ratio of <i>x</i>- and <i>y</i>-coefficients but not the same line. Multiply the first equation by 2: 4<i>x</i> + 6<i>y</i> = 24. For the left sides to match, <i>k</i> = 6; since 20 ≠ 24, the lines are parallel and distinct, so there is no solution.", "type": "spr"}, {"id": "t1m1-20", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Two-variable data: models and scatterplots", "stem": "A scientist models the height of a plant, <i>y</i> centimeters, <i>x</i> weeks after it was planted with the line of best fit <i>y</i> = 2.5<i>x</i> + 10. According to the model, what is the predicted height, in centimeters, of the plant 8 weeks after it was planted?", "choices": ["20", "25", "30", "35"], "answer": 2, "explanation": "Substitute <i>x</i> = 8: 2.5(8) + 10 = 20 + 10 = 30 centimeters.", "type": "mc"}, {"id": "t1m1-21", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear functions", "stem": "The function <i>f</i> is defined by <i>f</i>(<i>x</i>) = (<i>x</i> − 3)<sup>2</sup> + 4. What is the minimum value of <i>f</i>(<i>x</i>)?", "choices": ["−3", "3", "4", "7"], "answer": 2, "explanation": "This is vertex form <i>a</i>(<i>x</i> − <i>h</i>)<sup>2</sup> + <i>k</i> with vertex (3, 4). Because (<i>x</i> − 3)<sup>2</sup> is never negative, the smallest value of <i>f</i>(<i>x</i>) is 4, reached when <i>x</i> = 3.", "type": "mc"}, {"id": "t1m1-22", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "stem": "The measures of the three angles of a triangle are in the ratio 2 : 3 : 4. What is the measure, in degrees, of the largest angle?", "choices": ["40", "60", "80", "90"], "answer": 2, "explanation": "Let the angles be 2<i>n</i>, 3<i>n</i>, and 4<i>n</i>. They sum to 180°: 9<i>n</i> = 180, so <i>n</i> = 20. The largest angle is 4(20) = 80°.", "type": "mc"}]}, {"minutes": 35, "questions": [{"id": "t1m2-1", "sec": "math", "domain": "Algebra", "skill": "Linear equations in one variable", "stem": "If 5(<i>x</i> − 2) = 3<i>x</i> + 6, what is the value of <i>x</i>?", "choices": ["2", "4", "8", "16"], "answer": 2, "explanation": "Distribute: 5<i>x</i> − 10 = 3<i>x</i> + 6. Subtract 3<i>x</i> and add 10: 2<i>x</i> = 16, so <i>x</i> = 8.", "type": "mc"}, {"id": "t1m2-2", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Ratios, rates, proportions, and units", "stem": "A car travels 180 miles using 6 gallons of gas. At this rate, how many gallons of gas does the car need to travel 270 miles?", "choices": null, "answer": "9", "explanation": "The car gets 180/6 = 30 miles per gallon. 270 miles ÷ 30 miles per gallon = 9 gallons.", "type": "spr"}, {"id": "t1m2-3", "sec": "math", "domain": "Advanced Math", "skill": "Equivalent expressions", "stem": "Which expression is equivalent to (2<i>x</i><sup>3</sup><i>y</i>)(3<i>xy</i><sup>4</sup>)?", "choices": ["6<i>x</i><sup>4</sup><i>y</i><sup>5</sup>", "6<i>x</i><sup>3</sup><i>y</i><sup>4</sup>", "6<i>x</i><sup>4</sup><i>y</i><sup>4</sup>", "5<i>x</i><sup>4</sup><i>y</i><sup>5</sup>"], "answer": 0, "explanation": "Multiply the coefficients (2 × 3 = 6) and add exponents of like bases: <i>x</i><sup>3+1</sup> = <i>x</i><sup>4</sup> and <i>y</i><sup>1+4</sup> = <i>y</i><sup>5</sup>. Result: 6<i>x</i><sup>4</sup><i>y</i><sup>5</sup>.", "type": "mc"}, {"id": "t1m2-4", "sec": "math", "domain": "Algebra", "skill": "Linear equations in two variables", "stem": "What is the <i>y</i>-coordinate of the <i>y</i>-intercept of the graph of 2<i>x</i> − 5<i>y</i> = 10 in the <i>xy</i>-plane?", "choices": ["−5", "−2", "2", "5"], "answer": 1, "explanation": "The <i>y</i>-intercept is where <i>x</i> = 0: −5<i>y</i> = 10, so <i>y</i> = −2.", "type": "mc"}, {"id": "t1m2-5", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Percentages", "stem": "The price of an item is increased by 20%. Later, the new price is decreased by 20%. The final price is what percent of the original price?", "choices": ["80%", "96%", "100%", "104%"], "answer": 1, "explanation": "Multiply by the growth and decay factors: 1.20 × 0.80 = 0.96, so the final price is 96% of the original. The two 20% changes do not cancel because the decrease is taken from a larger amount.", "type": "mc"}, {"id": "t1m2-6", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "stem": "What is the sum of the solutions to the equation <i>x</i><sup>2</sup> − 5<i>x</i> − 14 = 0?", "choices": null, "answer": "5", "explanation": "Factor: (<i>x</i> − 7)(<i>x</i> + 2) = 0, so <i>x</i> = 7 or <i>x</i> = −2. Their sum is 7 + (−2) = 5. (Shortcut: for <i>x</i><sup>2</sup> + <i>bx</i> + <i>c</i> = 0, the sum of the solutions is −<i>b</i>.)", "type": "spr"}, {"id": "t1m2-7", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "stem": "A right circular cylinder has a radius of 3 centimeters and a height of 10 centimeters. What is the volume, in cubic centimeters, of the cylinder?", "choices": ["60π", "90π", "30π", "300π"], "answer": 1, "explanation": "V = π<i>r</i><sup>2</sup><i>h</i> = π(3)<sup>2</sup>(10) = 90π cubic centimeters. (This formula is on the reference sheet.)", "type": "mc"}, {"id": "t1m2-8", "sec": "math", "domain": "Algebra", "skill": "Linear functions", "stem": "For the linear function <i>f</i>, <i>f</i>(2) = 7 and <i>f</i>(6) = 19. What is the value of <i>f</i>(10)?", "choices": null, "answer": "31", "explanation": "Slope = (19 − 7)/(6 − 2) = 12/4 = 3. From <i>x</i> = 6 to <i>x</i> = 10 is 4 more units, so <i>f</i>(10) = 19 + 4(3) = 31.", "type": "spr"}, {"id": "t1m2-9", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "One-variable data: distributions and measures of center and spread", "stem": "What is the median of the data set 3, 8, 12, 15, 20, 21?", "choices": ["12", "13.17", "13.5", "15"], "answer": 2, "explanation": "There are 6 values (already in order), so the median is the average of the 3rd and 4th values: (12 + 15)/2 = 13.5. Choice B (about 13.17) is the mean, not the median.", "type": "mc"}, {"id": "t1m2-10", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear functions", "stem": "The function <i>f</i> is defined by <i>f</i>(<i>x</i>) = 2<i>x</i><sup>2</sup> − 3<i>x</i> + 1. Which expression is equivalent to <i>f</i>(<i>x</i> + 1)?", "choices": ["2<i>x</i><sup>2</sup> + <i>x</i>", "2<i>x</i><sup>2</sup> − 3<i>x</i> + 2", "2<i>x</i><sup>2</sup> + 7<i>x</i> + 6", "2<i>x</i><sup>2</sup> + <i>x</i> + 1"], "answer": 0, "explanation": "Replace every <i>x</i> with (<i>x</i> + 1): 2(<i>x</i> + 1)<sup>2</sup> − 3(<i>x</i> + 1) + 1 = 2<i>x</i><sup>2</sup> + 4<i>x</i> + 2 − 3<i>x</i> − 3 + 1 = 2<i>x</i><sup>2</sup> + <i>x</i>.", "type": "mc"}, {"id": "t1m2-11", "sec": "math", "domain": "Algebra", "skill": "Linear inequalities in one or two variables", "stem": "Which of the following describes all solutions to −3<i>x</i> + 4 &gt; 19?", "choices": ["<i>x</i> &lt; 5", "<i>x</i> &gt; 5", "<i>x</i> &lt; −5", "<i>x</i> &gt; −5"], "answer": 2, "explanation": "Subtract 4: −3<i>x</i> &gt; 15. Divide by −3 and <b>flip</b> the inequality sign: <i>x</i> &lt; −5.", "type": "mc"}, {"id": "t1m2-12", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Probability and conditional probability", "stem": "<p>The table summarizes whether 120 students in grades 10 and 11 joined a school club.</p><table class=\"data\"><tr><th></th><th>Grade 10</th><th>Grade 11</th><th>Total</th></tr><tr><th>Joined</th><td>18</td><td>27</td><td>45</td></tr><tr><th>Did not join</th><td>42</td><td>33</td><td>75</td></tr><tr><th>Total</th><td>60</td><td>60</td><td>120</td></tr></table>If one of the grade 11 students is chosen at random, what is the probability that the student joined the club? (Enter your answer as a fraction or decimal.)", "choices": null, "answer": "9/20", "explanation": "The question limits the choice to grade 11 students, so use the grade 11 column only: 27 joined out of 60. 27/60 = 9/20 = 0.45.", "type": "spr"}, {"id": "t1m2-13", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "stem": "<div class=\"eq\"><i>y</i> = <i>x</i><sup>2</sup> − 4<br><i>y</i> = 2<i>x</i> − 1</div>The graphs of the equations above intersect at two points. What is the positive <i>x</i>-coordinate of an intersection point?", "choices": null, "answer": "3", "explanation": "Set the right sides equal: <i>x</i><sup>2</sup> − 4 = 2<i>x</i> − 1, so <i>x</i><sup>2</sup> − 2<i>x</i> − 3 = 0. Factor: (<i>x</i> − 3)(<i>x</i> + 1) = 0, so <i>x</i> = 3 or <i>x</i> = −1. The positive value is 3.", "type": "spr"}, {"id": "t1m2-14", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "stem": "Triangle <i>ABC</i> is similar to triangle <i>DEF</i>, where <i>A</i>, <i>B</i>, and <i>C</i> correspond to <i>D</i>, <i>E</i>, and <i>F</i>, respectively. If <i>AB</i> = 6, <i>DE</i> = 15, and <i>BC</i> = 8, what is <i>EF</i>?", "choices": ["3.2", "12", "17", "20"], "answer": 3, "explanation": "Similar triangles have proportional sides. The scale factor from <i>ABC</i> to <i>DEF</i> is 15/6 = 2.5. <i>EF</i> = 8 × 2.5 = 20.", "type": "mc"}, {"id": "t1m2-15", "sec": "math", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "stem": "A theater sells adult tickets for $12 each and student tickets for $8 each. One night, 50 tickets were sold for a total of $480. How many adult tickets were sold?", "choices": ["10", "20", "25", "30"], "answer": 1, "explanation": "Let <i>a</i> = adult and <i>s</i> = student tickets. <i>a</i> + <i>s</i> = 50 and 12<i>a</i> + 8<i>s</i> = 480. Substitute <i>s</i> = 50 − <i>a</i>: 12<i>a</i> + 400 − 8<i>a</i> = 480, so 4<i>a</i> = 80 and <i>a</i> = 20.", "type": "mc"}, {"id": "t1m2-16", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear functions", "stem": "The function <i>f</i>(<i>x</i>) = 800(0.95)<sup><i>x</i></sup> models a quantity after <i>x</i> years. Which statement best describes how the quantity changes?", "choices": ["It decreases by 0.95 each year.", "It decreases by 95% each year.", "It increases by 5% each year.", "It decreases by 5% each year."], "answer": 3, "explanation": "The base 0.95 = 1 − 0.05, so each year the quantity is multiplied by 0.95, a 5% decrease per year. Choice B would require a base of 0.05.", "type": "mc"}, {"id": "t1m2-17", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Inference from sample statistics and margin of error", "stem": "A town chose 400 registered voters at random and asked whether they support building a new park. Of those surveyed, 56% said yes. The survey has a margin of error of 4 percentage points. Which conclusion is most appropriate?", "choices": ["It is plausible that between 52% and 60% of all registered voters in the town support the park.", "Exactly 56% of all registered voters in the town support the park.", "Between 52% and 60% of all voters in the state support the park.", "Fewer than 52% of the town's residents who are not registered voters support the park."], "answer": 0, "explanation": "A margin of error gives a range of plausible values for the whole population the sample was drawn from: 56% ± 4% is 52% to 60% of the town's registered voters. The survey can't pin down an exact value (B), and it says nothing about people outside the town (C) or about people who were not registered voters (D).", "type": "mc"}, {"id": "t1m2-18", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "stem": "In right triangle <i>PQR</i>, angle <i>R</i> is the right angle. The side opposite angle <i>P</i> has length 7, and the hypotenuse has length 25. What is cos <i>P</i>?", "choices": ["7/25", "7/24", "24/25", "24/7"], "answer": 2, "explanation": "The side adjacent to <i>P</i> is √(25<sup>2</sup> − 7<sup>2</sup>) = √(625 − 49) = √576 = 24. cos <i>P</i> = adjacent/hypotenuse = 24/25.", "type": "mc"}, {"id": "t1m2-19", "sec": "math", "domain": "Advanced Math", "skill": "Equivalent expressions", "stem": "The expression 4<i>x</i><sup>2</sup> + <i>bx</i> + 25, where <i>b</i> is a positive constant, is equivalent to (<i>mx</i> + <i>n</i>)<sup>2</sup> for some positive constants <i>m</i> and <i>n</i>. What is the value of <i>b</i>?", "choices": null, "answer": "20", "explanation": "(<i>mx</i> + <i>n</i>)<sup>2</sup> = <i>m</i><sup>2</sup><i>x</i><sup>2</sup> + 2<i>mnx</i> + <i>n</i><sup>2</sup>. So <i>m</i><sup>2</sup> = 4 (<i>m</i> = 2) and <i>n</i><sup>2</sup> = 25 (<i>n</i> = 5). Then <i>b</i> = 2<i>mn</i> = 2(2)(5) = 20. Check: (2<i>x</i> + 5)<sup>2</sup> = 4<i>x</i><sup>2</sup> + 20<i>x</i> + 25.", "type": "spr"}, {"id": "t1m2-20", "sec": "math", "domain": "Algebra", "skill": "Linear equations in two variables", "stem": "Line <i>ℓ</i> is perpendicular to the line <i>y</i> = (2/3)<i>x</i> + 1 and passes through the point (4, 0). What is the <i>y</i>-coordinate of the <i>y</i>-intercept of line <i>ℓ</i>?", "choices": ["−6", "8/3", "4", "6"], "answer": 3, "explanation": "Perpendicular slopes are negative reciprocals, so line <i>ℓ</i> has slope −3/2. Using point (4, 0): <i>y</i> = −(3/2)(<i>x</i> − 4) = −(3/2)<i>x</i> + 6. The <i>y</i>-intercept is 6.", "type": "mc"}, {"id": "t1m2-21", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear functions", "stem": "The function <i>h</i>(<i>x</i>) = <i>x</i><sup>2</sup> − 6<i>x</i> + <i>c</i>, where <i>c</i> is a constant, has exactly one <i>x</i>-intercept. What is the value of <i>c</i>?", "choices": ["3", "6", "9", "36"], "answer": 2, "explanation": "A quadratic has exactly one <i>x</i>-intercept when its discriminant <i>b</i><sup>2</sup> − 4<i>ac</i> = 0: (−6)<sup>2</sup> − 4(1)(<i>c</i>) = 0, so 36 = 4<i>c</i> and <i>c</i> = 9. Check: <i>x</i><sup>2</sup> − 6<i>x</i> + 9 = (<i>x</i> − 3)<sup>2</sup>.", "type": "mc"}, {"id": "t1m2-22", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "stem": "What is the area of an equilateral triangle with side length 10?", "choices": ["50√3", "25√3", "25", "100"], "answer": 1, "explanation": "Drawing an altitude splits the triangle into two 30°-60°-90° triangles with short leg 5, so the height is 5√3. Area = (1/2)(10)(5√3) = 25√3.", "type": "mc"}]}]}]}, {"id": 2, "name": "Practice Test 2", "sections": [{"id": "rw", "name": "Reading and Writing", "modules": [{"minutes": 32, "questions": [{"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "The hiking guide warned that the trail's final section was <span class=\"blank\">______</span>, with loose rocks and steep drop-offs that required careful footing.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["monotonous", "scenic", "brief", "treacherous"], "explanation": "Loose rocks and steep drop-offs make a trail dangerous: <b>treacherous</b>. A guide \"warned\" about it, so a positive or neutral word like \"scenic\" or \"brief\" doesn't fit.", "type": "mc", "answer": 3, "id": "t2rw1-1"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Rather than <span class=\"blank\">______</span> the results of their failed experiment, the team published them, arguing that other scientists could learn from their mistakes.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["analyzing", "praising", "repeating", "concealing"], "explanation": "\"Rather than\" signals the opposite of publishing. The opposite of making results public is hiding them: <b>concealing</b>.", "type": "mc", "answer": 3, "id": "t2rw1-2"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "The mayor's speech was <span class=\"blank\">______</span>; it lasted only three minutes but still covered every major point of her plan.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["succinct", "lengthy", "confusing", "hostile"], "explanation": "A short speech that still covers every main point is brief and clear: <b>succinct</b>. \"Lengthy\" contradicts \"only three minutes.\"", "type": "mc", "answer": 0, "id": "t2rw1-3"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Chef Amara Diallo is known for her <span class=\"blank\">______</span> approach to cooking: she rarely follows recipes and often invents new dishes using whatever ingredients happen to be available.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["cautious", "traditional", "improvisational", "expensive"], "explanation": "Inventing dishes on the spot without recipes is <b>improvisational</b>. \"Traditional\" and \"cautious\" suggest following established methods.", "type": "mc", "answer": 2, "id": "t2rw1-4"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "<p>The following text is from an original short story.</p><p>The old ferry had crossed the river twice a day for forty years, and Captain Reyes knew every ripple of the current. <u>So when the water near the eastern dock began to swirl in a pattern he had never seen before, he cut the engine and waited.</u> Ten minutes later, a section of the riverbank collapsed exactly where the ferry would have docked.</p>", "stem": "Which choice best describes the function of the underlined sentence in the text as a whole?", "choices": ["It describes the history of the ferry and the river it crosses.", "It suggests that the captain is new to the job and unsure of himself.", "It explains the scientific reasons the riverbank collapsed.", "It shows that the captain's long experience allows him to notice something unusual and respond with caution."], "explanation": "The first sentence establishes his experience; the underlined sentence shows him spotting something he'd \"never seen before\" and stopping. The last sentence shows that caution saved the ferry.", "type": "mc", "answer": 3, "id": "t2rw1-5"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "For many years, astronomers classified Pluto as the ninth planet of the solar system. After several objects of similar size were discovered in the outer solar system in the early 2000s, however, the International Astronomical Union adopted a formal definition of \"planet\" in 2006. Because Pluto has not cleared its orbital neighborhood of other objects, it no longer met the definition and was reclassified as a dwarf planet.", "stem": "Which choice best states the main purpose of the text?", "choices": ["To explain how and why Pluto's classification changed", "To describe the surface features of Pluto", "To compare Pluto's size with that of Earth", "To argue that Pluto should once again be called a planet"], "explanation": "The text traces Pluto's old status, the event that prompted a new definition, and the reason Pluto no longer fits it. It takes no position and describes neither Pluto's surface nor Earth.", "type": "mc", "answer": 0, "id": "t2rw1-6"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "Some economists argue that raising the minimum wage causes businesses to hire fewer workers. Others point to studies finding little change in employment after wage increases. Economist Laila Hassan suggests that both views may be partly correct: her analysis indicates that the effect depends on how large the increase is compared with typical local wages.", "stem": "Which choice best describes the overall structure of the text?", "choices": ["It presents one view and then explains why that view has been abandoned.", "It describes a single study in detail and then criticizes its methods.", "It presents two opposing views and then describes a position that partly reconciles them.", "It traces the history of minimum wage laws in one country."], "explanation": "View 1 (fewer jobs) → View 2 (little change) → Hassan's idea that \"both views may be partly correct.\" That is a reconciling position, not a rejection.", "type": "mc", "answer": 2, "id": "t2rw1-7"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "<p><b>Text 1</b><br>Architects have long assumed that people prefer homes with large windows mainly because natural light improves their mood.</p><p><b>Text 2</b><br>In a survey of 2,000 homeowners, sociologist Theo Mbeki found that many respondents valued large windows mostly for the views they provided rather than for the light. Several respondents whose homes faced brick walls said they would actually prefer smaller windows for the sake of privacy.</p>", "stem": "Based on the texts, how would Mbeki (Text 2) most likely respond to the assumption described in Text 1?", "choices": ["He would agree that light is the only reason people value large windows.", "He would argue that no homeowners want large windows.", "He would suggest that the assumption overlooks other reasons people may or may not value large windows.", "He would argue that natural light makes most people's mood worse."], "explanation": "Mbeki found people care about views and privacy, factors the light-and-mood assumption ignores. He doesn't claim light is harmful or that nobody wants large windows.", "type": "mc", "answer": 2, "id": "t2rw1-8"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Central Ideas and Details", "passage": "When regular radio broadcasts began in the United States in the 1920s, many newspaper publishers worried that people would stop buying newspapers. Instead, newspaper sales continued to grow throughout the decade. Some historians argue that radio may actually have increased interest in the news: listeners who heard brief bulletins often bought a paper to read the full story.", "stem": "Which choice best states the main idea of the text?", "choices": ["Radio news bulletins in the 1920s were longer and more detailed than newspaper stories.", "Radio did not reduce newspaper sales as publishers had feared and may even have increased interest in the news.", "Radio quickly replaced newspapers as most people's main source of news.", "Newspaper publishers were responsible for creating the first radio stations."], "explanation": "The fear (\"people would stop buying newspapers\") didn't come true (\"Instead, … sales continued to grow\"), and historians suggest radio boosted interest. The bulletins were \"brief,\" so choice A contradicts the text.", "type": "mc", "answer": 1, "id": "t2rw1-9"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Central Ideas and Details", "passage": "<p>The following text is from an original short story.</p><p>Marcus had always thought of his neighbor, Mrs. Abernathy, as stern. She never waved, and she frowned at children who cut across her lawn. But the winter his family's furnace broke, it was Mrs. Abernathy who appeared at the door with a space heater and a casserole, insisting they keep both as long as they needed.</p>", "stem": "Based on the text, what is true about Mrs. Abernathy?", "choices": ["She is a relative of Marcus's family.", "She repaired the furnace in Marcus's home.", "She has started waving to the children in the neighborhood.", "Her generosity during a difficult time contrasts with Marcus's earlier impression of her."], "explanation": "\"But\" marks the contrast between Marcus's view of her as stern and her kind act. She brought a heater, not a repair, and the text never mentions waving afterward.", "type": "mc", "answer": 3, "id": "t2rw1-10"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Textual", "passage": "A historian argues that a small Midwestern town's rapid growth in the late 1800s was driven mainly by the arrival of the railroad.", "stem": "Which finding, if true, would most directly support the historian's argument?", "choices": ["The town published its first newspaper several years before the railroad arrived.", "The town's population tripled in the ten years after its railroad station opened, following several decades of almost no growth.", "The railroad line was built by a company based in another state.", "Nearby towns that the railroad bypassed grew at the same rate during the same period."], "explanation": "Growth that suddenly took off right after the railroad arrived, after decades without growth, links the two. If towns without railroads grew just as fast (choice D), that would <i>weaken</i> the argument.", "type": "mc", "answer": 1, "id": "t2rw1-11"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Textual", "passage": "In an original short story, the narrator describes a character named Odette as deeply curious about the natural world.", "stem": "Which quotation from the story most effectively illustrates the narrator's description?", "choices": ["\"She often arrived late to dinner, her shoes untied.\"", "\"Odette spent whole afternoons turning over stones in the creek, filling a notebook with sketches of every beetle and snail she found underneath.\"", "\"Odette's older brother liked to tease her about her messy handwriting.\"", "\"Odette's bedroom was painted a pale yellow that glowed in the morning light.\""], "explanation": "Spending afternoons investigating and sketching creek animals shows curiosity about nature. The others describe her room, habits, or family.", "type": "mc", "answer": 1, "id": "t2rw1-12"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Quantitative", "passage": "<p>A student surveyed students at one high school about how much they sleep on school nights. The student claims that average sleep decreases as grade level increases.</p><table class=\"data\"><caption>Average hours of sleep on school nights</caption><tr><th>Grade</th><th>Hours</th></tr><tr><td>9</td><td>7.6</td></tr><tr><td>10</td><td>7.2</td></tr><tr><td>11</td><td>6.9</td></tr><tr><td>12</td><td>6.7</td></tr></table>", "stem": "Which choice most effectively uses data from the table to support the student's claim?", "choices": ["Ninth graders averaged 7.6 hours of sleep and twelfth graders averaged 6.7 hours, and each grade in between averaged less than the grade before it.", "Eleventh graders averaged less than 7 hours of sleep on school nights.", "Tenth graders averaged 7.2 hours of sleep on school nights.", "Ninth graders averaged more sleep than students in any other grade."], "explanation": "The claim is about a steady pattern across all grades. Only choice A shows sleep falling at every step from grade 9 to grade 12.", "type": "mc", "answer": 0, "id": "t2rw1-13"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Inferences", "passage": "Glass frogs, which live in Central and South American rainforests, have partly see-through skin. A recent study found that while glass frogs sleep, they pull most of their red blood cells out of circulation and store them in the liver, which makes their bodies far more transparent. Because the frogs sleep during the day on the undersides of green leaves, researchers suggest that <span class=\"blank\">______</span>", "stem": "Which choice most logically completes the text?", "choices": ["becoming more transparent may help sleeping frogs avoid being seen by predators.", "storing blood in the liver causes the frogs' skin to turn green.", "glass frogs need extra red blood cells in order to fall asleep.", "glass frogs are active only during the daytime."], "explanation": "A nearly transparent frog on a green leaf would blend in, making it harder for predators to spot while it sleeps. The frogs sleep during the day, so they are not \"active only during the daytime.\"", "type": "mc", "answer": 0, "id": "t2rw1-14"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Inferences", "passage": "A bookstore owner noticed that sales of mystery novels rose sharply during the month the store set up a display of mysteries near its entrance. During that same month, however, a popular television series based on a mystery novel premiered, and bookstores without such displays also reported higher mystery sales. Therefore, the owner cannot conclude that <span class=\"blank\">______</span>", "stem": "Which choice most logically completes the text?", "choices": ["the display was the main reason for the store's increase in mystery sales.", "mystery novels are popular with the store's customers.", "other bookstores sell mystery novels.", "television series can affect what books people buy."], "explanation": "Stores without displays also saw higher sales, and the TV series is another possible cause, so the owner can't credit the display. The other choices are either supported by the text or irrelevant to what the owner can't conclude.", "type": "mc", "answer": 0, "id": "t2rw1-15"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "The Amazon River carries more water than any other river in the <span class=\"blank\">______</span> it discharges roughly one-fifth of all the fresh water that flows from rivers into the oceans.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["world", "world that", "world,", "world;"], "explanation": "Two independent clauses can be joined with a semicolon. A comma alone is a comma splice; no punctuation is a run-on.", "type": "mc", "answer": 3, "id": "t2rw1-16"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "The Apollo 11 lunar <span class=\"blank\">______</span> landed on the Moon in July 1969 with astronauts Neil Armstrong and Buzz Aldrin aboard.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["module—<i>Eagle</i>,", "module, <i>Eagle</i>", "module, <i>Eagle</i>,", "module <i>Eagle</i>,"], "explanation": "Apollo 11 had only one lunar module, so its name is extra (nonessential) information and must be set off on <i>both</i> sides with matching punctuation: two commas. Mixing a dash with a comma, or using only one comma, is incorrect.", "type": "mc", "answer": 2, "id": "t2rw1-17"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "Wildlife photographer Ines Carvalho waited six hours in a camouflaged <span class=\"blank\">______</span> then, just before sunset, the shy heron finally stepped out of the reeds.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["tent,", "tent", "tent, which", "tent;"], "explanation": "\"Then\" isn't a conjunction, so the two independent clauses need a semicolon (or a period). A comma creates a comma splice.", "type": "mc", "answer": 3, "id": "t2rw1-18"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "Although the recipe calls for fresh <span class=\"blank\">______</span> dried basil can be used instead.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["basil,", "basil:", "basil.", "basil;"], "explanation": "\"Although the recipe calls for fresh basil\" is a dependent clause, so a comma connects it to the main clause. The other marks would leave it as a fragment.", "type": "mc", "answer": 0, "id": "t2rw1-19"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "The team of engineers <span class=\"blank\">______</span> currently testing a new design for wind turbine blades.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["have been", "is", "were", "are"], "explanation": "The subject is the singular noun \"team,\" and \"currently\" calls for present tense, so \"is\" is correct.", "type": "mc", "answer": 1, "id": "t2rw1-20"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "By the time the rescue boat arrived, the stranded hikers <span class=\"blank\">______</span> on the island for three days.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["are", "have been", "had been", "will be"], "explanation": "The hikers' stay happened before another past event (the boat arriving), so the past perfect \"had been\" is needed.", "type": "mc", "answer": 2, "id": "t2rw1-21"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "The museum's collection includes artifacts from ancient Egypt, ancient Greece, and <span class=\"blank\">______</span>", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["from Rome in ancient times.", "of ancient Rome's.", "Rome, which was ancient.", "ancient Rome."], "explanation": "Items in a list should be parallel: \"ancient Egypt, ancient Greece, and ancient Rome.\"", "type": "mc", "answer": 3, "id": "t2rw1-22"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "Tardigrades are tiny animals known for surviving extreme conditions. <span class=\"blank\">______</span> they can withstand temperatures close to absolute zero and survive for years without water.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["However,", "For example,", "Still,", "Instead,"], "explanation": "The second sentence gives specific examples of the extreme conditions mentioned in the first.", "type": "mc", "answer": 1, "id": "t2rw1-23"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "Many users found the first version of the app difficult to navigate. <span class=\"blank\">______</span> the developers redesigned its menus based on user feedback.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["As a result,", "Similarly,", "For instance,", "Nonetheless,"], "explanation": "The redesign was a response to the difficulty, a cause-and-effect relationship.", "type": "mc", "answer": 0, "id": "t2rw1-24"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "Some birds, such as Baltimore orioles, fly south every fall to spend the winter in warmer regions. <span class=\"blank\">______</span> others, such as northern cardinals, remain in the same area all year.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["Likewise,", "As a result,", "In contrast,", "Therefore,"], "explanation": "Birds that stay all year are the opposite of birds that migrate, so a contrast is needed.", "type": "mc", "answer": 2, "id": "t2rw1-25"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "<p>While researching a topic, a student has taken the following notes:</p><ul><li>The Riverside Bike Share program launched in 2021.</li><li>It offers 300 bikes at 25 stations.</li><li>In its first year, riders took 85,000 trips.</li><li>In its second year, riders took 140,000 trips.</li></ul>", "stem": "The student wants to emphasize how much the use of the program grew. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["The Riverside Bike Share program offers 300 bikes at 25 stations.", "Riverside Bike Share has 25 stations.", "Riders took 85,000 trips on Riverside Bike Share in its first year and 140,000 trips in its second year.", "Riverside Bike Share launched in 2021 with 300 bikes."], "explanation": "Growth in use is shown by comparing the number of trips across years. Only choice C includes both years' trip counts.", "type": "mc", "answer": 2, "id": "t2rw1-26"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "<p>While researching a topic, a student has taken the following notes:</p><ul><li>Researchers at a university studied whether listening to background music affects how well students solve math problems.</li><li>120 students solved problems either in silence or while listening to instrumental music.</li><li>Students working in silence solved slightly more problems correctly.</li><li>The difference between the groups was small.</li></ul>", "stem": "The student wants to present the aim of the study. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["In the study, the difference between the two groups was small.", "Researchers wanted to find out whether background music affects students' ability to solve math problems.", "A study of background music and math problem-solving included 120 students.", "Students working in silence solved slightly more math problems correctly than students listening to music."], "explanation": "The \"aim\" is what the researchers set out to learn, not their results or sample size. Only choice B states the purpose.", "type": "mc", "answer": 1, "id": "t2rw1-27"}]}, {"minutes": 32, "questions": [{"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "The documentary's portrayal of the scientist is notably <span class=\"blank\">______</span>: it celebrates her achievements but also examines her mistakes and the criticism she faced.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["superficial", "hostile", "flattering", "balanced"], "explanation": "Showing both achievements and mistakes is a fair, two-sided portrayal: <b>balanced</b>. \"Flattering\" and \"hostile\" are one-sided, and examining criticism isn't \"superficial.\"", "type": "mc", "answer": 3, "id": "t2rw2-1"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Because the bridge's original blueprints had been lost, engineers had to <span class=\"blank\">______</span> its internal structure from careful measurements and images taken with scanning equipment.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["ignore", "infer", "celebrate", "duplicate"], "explanation": "Without blueprints, engineers had to work out the structure from indirect evidence: they had to <b>infer</b> it.", "type": "mc", "answer": 1, "id": "t2rw2-2"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "The professor's lectures were so <span class=\"blank\">______</span> that students often left with more questions than answers, unsure what the main point had been.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["lucid", "convoluted", "brief", "popular"], "explanation": "Lectures that leave students unsure of the main point are complicated and hard to follow: <b>convoluted</b>. \"Lucid\" (clear) is the opposite.", "type": "mc", "answer": 1, "id": "t2rw2-3"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "The museum's new acquisitions <u>reflect</u> the curator's interest in West African textiles: more than half of the pieces purchased this year are woven cloths from the region.", "stem": "As used in the text, what does the word \"reflect\" most nearly mean?", "choices": ["bounce back", "show", "mirror light", "think carefully"], "explanation": "The purchases are evidence of the curator's interest; they <b>show</b> it. The other meanings of \"reflect\" (mirroring light, thinking) don't fit.", "type": "mc", "answer": 1, "id": "t2rw2-4"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "<p>The following text is from an original poem.</p><p class=\"poem\">I planted the oak as a boy,<br>a twig I could close in my fist.<br>Now my grandchildren climb it<br>and argue over whose branch is whose,<br>and I sit in a shade<br>I never imagined I'd see.</p>", "stem": "Which choice best describes the overall structure of the text?", "choices": ["It describes a storm and the damage it caused to a tree.", "It lists several types of trees the speaker has planted.", "It argues that people should plant trees in their communities.", "It contrasts an action the speaker took long ago with its results in the present."], "explanation": "The poem moves from \"as a boy\" (a tiny twig) to \"Now\" (a tree big enough to climb and give shade). It contains no storm, argument, or list of trees.", "type": "mc", "answer": 3, "id": "t2rw2-5"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "Many people believe that bats are blind, but no bat species is blind, and some bats have excellent eyesight. <u>Many bats use echolocation—making sounds and listening for the echoes—to navigate in the dark, but this ability adds to their vision rather than replacing it.</u>", "stem": "Which choice best describes the function of the underlined sentence in the text as a whole?", "choices": ["It clarifies how bats' use of echolocation relates to their ability to see.", "It introduces a counterargument that the text then rejects.", "It presents evidence that most bats are actually blind.", "It describes how one particular bat species finds food."], "explanation": "After stating that bats aren't blind, the text explains that echolocation works alongside sight. It doesn't argue for blindness or focus on one species.", "type": "mc", "answer": 0, "id": "t2rw2-6"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "In the 1870s, a group of painters in Paris began exhibiting works that many critics mocked as unfinished sketches. These artists, later known as the Impressionists, often painted quickly and outdoors to capture changing light. Within a few decades, their once-ridiculed style had become one of the most celebrated in the history of art.", "stem": "Which choice best describes the overall structure of the text?", "choices": ["It compares the methods of two rival groups of artists.", "It argues that the critics' original judgment was correct.", "It explains a painting technique without discussing how it was received.", "It describes an early negative reaction to a group of artists and then their later acclaim."], "explanation": "Early mockery → description of the artists' approach → later celebration. The text discusses only one group, and its ending shows the critics' view did not hold up.", "type": "mc", "answer": 3, "id": "t2rw2-7"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "<p><b>Text 1</b><br>Some linguists believe that young children learn language mainly by imitating the speech of the adults around them.</p><p><b>Text 2</b><br>Linguist Nadia Romero notes that young children often produce forms they have never heard adults use, such as \"goed\" instead of \"went\" or \"mouses\" instead of \"mice.\" According to Romero, such errors show that children are not simply copying speech but are applying grammatical rules they have worked out for themselves.</p>", "stem": "Based on the texts, how would Romero (Text 2) most likely respond to the view presented in Text 1?", "choices": ["She would argue that imitation can't fully explain language learning, since children create forms they have not heard.", "She would argue that adults commonly say \"goed\" and \"mouses.\"", "She would agree that children learn language only by imitating adults.", "She would claim that children do not learn grammatical rules."], "explanation": "Errors like \"goed\" can't come from copying adults, which shows children apply rules on their own. That challenges the idea that imitation is the main way children learn.", "type": "mc", "answer": 0, "id": "t2rw2-8"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Central Ideas and Details", "passage": "Long before electric refrigerators, people in many hot, dry regions kept food cool with a device sometimes called a pot-in-pot cooler. A smaller clay pot is placed inside a larger one, and the space between them is filled with wet sand. As water evaporates from the surface of the outer pot, it carries heat away, keeping the inner pot's contents cooler than the surrounding air.", "stem": "Which choice best states the main idea of the text?", "choices": ["Wet sand heats food faster than dry sand does.", "A simple device uses evaporation to keep food cool without electricity.", "Electric refrigerators are unnecessary in hot regions.", "Clay pots were invented to store sand."], "explanation": "The text explains what a pot-in-pot cooler is and how evaporation cools the food inside. It doesn't argue against refrigerators.", "type": "mc", "answer": 1, "id": "t2rw2-9"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Central Ideas and Details", "passage": "<p>The following text is from an original short story.</p><p>Every summer, the Ortega family drove twelve hours to the lake, and every summer Ana complained the entire way. This year, though, she had her learner's permit, and her father let her take the wheel for the final stretch of quiet country road. When they pulled up to the cabin, Ana realized she hadn't complained once—and that she was already looking forward to the drive home.</p>", "stem": "Which choice best states the main idea of the text?", "choices": ["The Ortega family decides to stop making the trip to the lake.", "Ana dislikes the lake and wishes her family would vacation somewhere else.", "Being trusted with part of the drive changes Ana's attitude toward the trip.", "Ana's father is tired of driving and asks her to drive the whole way."], "explanation": "Ana used to complain the whole way, but after driving part of it she didn't complain and even looks forward to the return trip. She drove only \"the final stretch.\"", "type": "mc", "answer": 2, "id": "t2rw2-10"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Textual", "passage": "Researchers hypothesize that young males of a certain songbird species learn their songs mainly from their fathers rather than from other adult males nearby.", "stem": "Which finding, if true, would most directly support the researchers' hypothesis?", "choices": ["Adult males of the species sing more often in the spring than in the fall.", "Females of the species prefer males that sing more complex songs.", "Young males that could hear both their fathers and other adult males developed songs that closely matched their fathers' songs rather than the other males' songs.", "Young males that heard no adult songs at all developed unusual songs."], "explanation": "When young birds could learn from either source, they copied their fathers. That directly supports \"mainly from their fathers.\" Choice D shows learning matters but not <i>whom</i> they learn from.", "type": "mc", "answer": 2, "id": "t2rw2-11"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Textual", "passage": "In an original poem, the speaker expresses a longing for a faraway home.", "stem": "Which quotation from the poem most effectively illustrates this longing?", "choices": ["\"Each night I trace the coastline on my map / and whisper the names of streets I used to walk.\"", "\"The market here is loud and full of color.\"", "\"My new coat is warmer than the old one was.\"", "\"The train leaves the station at half past nine.\""], "explanation": "Tracing a map each night and whispering the names of old streets shows the speaker missing a distant place. The other lines describe the present without longing.", "type": "mc", "answer": 0, "id": "t2rw2-12"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Quantitative", "passage": "<p>A student is comparing visitor numbers at three state parks and claims that, of the three, Park C had the greatest percentage increase in visitors from 2018 to 2023.</p><table class=\"data\"><caption>Annual visitors (thousands)</caption><tr><th>Park</th><th>2018</th><th>2023</th></tr><tr><td>Park A</td><td>120</td><td>150</td></tr><tr><td>Park B</td><td>210</td><td>190</td></tr><tr><td>Park C</td><td>80</td><td>170</td></tr></table>", "stem": "Which choice most effectively uses data from the table to support the student's claim?", "choices": ["Park B had more visitors than either of the other parks in 2018.", "Park A had 150,000 visitors in 2023.", "Park C's visitors more than doubled, from 80,000 to 170,000, while Park A's rose by only 25% and Park B's declined.", "Park C had the fewest visitors of the three parks in 2018."], "explanation": "Percentage growth: Park A (120 → 150) rose 25%; Park B fell; Park C (80 → 170) rose about 113%. Only choice C compares the growth of all three parks.", "type": "mc", "answer": 2, "id": "t2rw2-13"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Inferences", "passage": "In the 1800s, many cities experienced deadly outbreaks of cholera. At the time, most doctors believed the disease spread through \"bad air.\" During one outbreak, a physician noticed that nearly all of the victims in one neighborhood had drawn water from the same public pump, while workers at a nearby brewery, who drank beer made with water from the brewery's own well, were largely unaffected. These observations suggested that <span class=\"blank\">______</span>", "stem": "Which choice most logically completes the text?", "choices": ["the public pump had no connection to the outbreak.", "cholera might spread through contaminated water rather than through the air.", "drinking beer causes people to become sick with cholera.", "\"bad air\" was the main cause of the outbreak in that neighborhood."], "explanation": "The illness tracked with one water source, and people who used a different water source stayed healthy even though they breathed the same neighborhood air. That points to water, not air.", "type": "mc", "answer": 1, "id": "t2rw2-14"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Inferences", "passage": "A city planted trees along several streets that previously had none. Over the next two summers, sensors showed that the average daytime temperature on those streets was about 2°C lower than on nearby streets without trees, even though the two sets of streets were similar in width, traffic, and type of pavement. The findings suggest that <span class=\"blank\">______</span>", "stem": "Which choice most logically completes the text?", "choices": ["the type of pavement explains the difference in temperature.", "the sensors on the streets with trees were not working properly.", "the trees likely contributed to the lower temperatures.", "the streets with trees were wider than the streets without trees."], "explanation": "The streets were alike in width, traffic, and pavement, so those can't explain the difference; the trees are the key difference. Choices A and D contradict the text.", "type": "mc", "answer": 2, "id": "t2rw2-15"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "The museum's newest exhibit, which opened last <span class=\"blank\">______</span> has already attracted more than 10,000 visitors.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["week—", "week,", "week", "week;"], "explanation": "The clause \"which opened last week\" begins with a comma, so it must also end with a comma to separate it from the rest of the sentence.", "type": "mc", "answer": 1, "id": "t2rw2-16"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "Marie Curie was the first person to win Nobel Prizes in two different <span class=\"blank\">______</span> physics in 1903 and chemistry in 1911.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["sciences:", "sciences, and", "sciences, these were", "sciences;"], "explanation": "A colon introduces information that explains what came before (which two sciences). A semicolon needs an independent clause after it, and \"sciences, these were\" creates a comma splice.", "type": "mc", "answer": 0, "id": "t2rw2-17"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "To prepare for the marathon, Desmond ran five miles every <span class=\"blank\">______</span> on weekends, he ran even farther.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["morning,", "morning", "morning;", "morning that"], "explanation": "Two independent clauses (\"Desmond ran…\" and \"he ran even farther\") need a semicolon between them. A comma is a comma splice.", "type": "mc", "answer": 2, "id": "t2rw2-18"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "The ancient city of Petra, carved into rose-colored sandstone <span class=\"blank\">______</span> is located in present-day Jordan.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["cliffs;", "cliffs:", "cliffs,", "cliffs"], "explanation": "The descriptive phrase \"carved into rose-colored sandstone cliffs\" starts with a comma, so it must end with one before the verb \"is.\"", "type": "mc", "answer": 2, "id": "t2rw2-19"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "Neither the coach nor the players <span class=\"blank\">______</span> expecting the storm to delay the game.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["was", "has been", "is", "were"], "explanation": "With \"neither … nor,\" the verb agrees with the closer subject, \"players,\" which is plural: \"were.\"", "type": "mc", "answer": 3, "id": "t2rw2-20"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "The flock of geese <span class=\"blank\">______</span> to change direction all at once, as if responding to a single signal.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["seems", "have seemed", "are seeming", "seem"], "explanation": "The subject is the singular \"flock\" (\"of geese\" is a prepositional phrase), so the verb is the singular \"seems.\"", "type": "mc", "answer": 0, "id": "t2rw2-21"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "The novel's main character, <span class=\"blank\">______</span> dreams of becoming an astronaut, spends most of the story working on her family's farm.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["whose", "whom", "which", "who"], "explanation": "The pronoun is the subject of \"dreams\" and refers to a person, so \"who\" is correct. \"Whom\" is for objects, and \"which\" is for things.", "type": "mc", "answer": 3, "id": "t2rw2-22"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "The violinist practiced for hours every day. <span class=\"blank\">______</span> she rarely performed in public, preferring to play for small groups of friends.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["For example,", "However,", "Similarly,", "Therefore,"], "explanation": "Someone who practices that much might be expected to perform often, so \"rarely performed\" is a contrast.", "type": "mc", "answer": 1, "id": "t2rw2-23"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "To make paper, workers first soak wood chips in a chemical solution that breaks them down into fibers. <span class=\"blank\">______</span> the fibers are pressed into thin sheets and dried.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["Regardless,", "For instance,", "Next,", "In contrast,"], "explanation": "The sentences describe steps in a process (\"first … \"), so a sequence word, \"Next,\" fits.", "type": "mc", "answer": 2, "id": "t2rw2-24"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "When it was first published, some critics dismissed the novel as too long and confusing. <span class=\"blank\">______</span> it is now widely considered one of the greatest novels of the century.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["In other words,", "Similarly,", "Consequently,", "Nonetheless,"], "explanation": "Being called one of the greatest novels contrasts with the early criticism, so \"Nonetheless\" (in spite of that) is logical. The criticism didn't cause the acclaim, so \"Consequently\" is wrong.", "type": "mc", "answer": 3, "id": "t2rw2-25"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "<p>While researching a topic, a student has taken the following notes:</p><ul><li>The kākāpō is a large, flightless parrot found only in New Zealand.</li><li>It is active mainly at night.</li><li>It is critically endangered.</li><li>Conservationists moved all known kākāpō to islands free of predators.</li><li>The population grew from about 50 birds in 1995 to more than 200 in recent years.</li></ul>", "stem": "The student wants to highlight the success of conservation efforts. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["After conservationists moved all known kākāpō to predator-free islands, the population grew from about 50 birds in 1995 to more than 200.", "The kākāpō is active mainly at night.", "The kākāpō, a parrot found only in New Zealand, is critically endangered.", "The kākāpō is a large, flightless parrot found only in New Zealand."], "explanation": "Success is shown by the conservation action and the population increase that followed. Only choice A includes both.", "type": "mc", "answer": 0, "id": "t2rw2-26"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "<p>While researching a topic, a student has taken the following notes:</p><ul><li>Students in a science class tested two brands of paper towels.</li><li>One sheet of Brand X absorbed 45 milliliters of water.</li><li>One sheet of Brand Y absorbed 30 milliliters of water.</li><li>Brand X costs $0.04 per sheet.</li><li>Brand Y costs $0.02 per sheet.</li></ul>", "stem": "The student wants to suggest that Brand Y may be the better choice for shoppers on a budget. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["A sheet of Brand X absorbed more water than a sheet of Brand Y did.", "Students in a science class tested two brands of paper towels.", "One sheet of Brand X absorbed 45 milliliters of water.", "Although a sheet of Brand Y absorbed less water than a sheet of Brand X (30 mL versus 45 mL), it cost only half as much."], "explanation": "Budget shoppers care about cost relative to performance. Brand Y costs half as much while absorbing two-thirds as much water, so it gives more absorption per dollar (1,500 mL per dollar versus 1,125). Choice D makes this case; the others either favor Brand X or ignore cost.", "type": "mc", "answer": 3, "id": "t2rw2-27"}]}]}, {"id": "math", "name": "Math", "modules": [{"minutes": 35, "questions": [{"id": "t2m1-1", "sec": "math", "domain": "Algebra", "skill": "Linear equations in one variable", "stem": "If <i>x</i>/4 + 3 = 8, what is the value of <i>x</i>?", "choices": ["5", "11", "20", "44"], "answer": 2, "explanation": "Subtract 3: <i>x</i>/4 = 5. Multiply by 4: <i>x</i> = 20.", "type": "mc"}, {"id": "t2m1-2", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Ratios, rates, proportions, and units", "stem": "On a map, 1 inch represents 25 miles. How many miles are represented by 3.2 inches on the map?", "choices": null, "answer": "80", "explanation": "3.2 × 25 = 80 miles.", "type": "spr"}, {"id": "t2m1-3", "sec": "math", "domain": "Advanced Math", "skill": "Equivalent expressions", "stem": "Which expression is equivalent to 3(<i>x</i><sup>2</sup> − 2<i>x</i>) − (<i>x</i><sup>2</sup> + 4)?", "choices": ["4<i>x</i><sup>2</sup> − 6<i>x</i> + 4", "2<i>x</i><sup>2</sup> − 6<i>x</i> + 4", "2<i>x</i><sup>2</sup> − 6<i>x</i> − 4", "2<i>x</i><sup>2</sup> − 2<i>x</i> − 4"], "answer": 2, "explanation": "Distribute: 3<i>x</i><sup>2</sup> − 6<i>x</i> − <i>x</i><sup>2</sup> − 4. Combine like terms: 2<i>x</i><sup>2</sup> − 6<i>x</i> − 4. Watch the negative sign in front of the parentheses: it changes +4 to −4.", "type": "mc"}, {"id": "t2m1-4", "sec": "math", "domain": "Algebra", "skill": "Linear functions", "stem": "The function <i>g</i> is defined by <i>g</i>(<i>x</i>) = −2<i>x</i> + 11. For what value of <i>x</i> does <i>g</i>(<i>x</i>) = 3?", "choices": null, "answer": "4", "explanation": "Set −2<i>x</i> + 11 = 3. Subtract 11: −2<i>x</i> = −8. Divide by −2: <i>x</i> = 4.", "type": "spr"}, {"id": "t2m1-5", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Percentages", "stem": "18 is what percent of 72?", "choices": ["4%", "18%", "25%", "40%"], "answer": 2, "explanation": "18/72 = 0.25 = 25%.", "type": "mc"}, {"id": "t2m1-6", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "stem": "Two lines intersect at a point, forming a pair of vertical angles that measure (3<i>x</i> + 10)° and (5<i>x</i> − 30)°. What is the value of <i>x</i>?", "choices": ["10", "20", "25", "40"], "answer": 1, "explanation": "Vertical angles are equal: 3<i>x</i> + 10 = 5<i>x</i> − 30. So 40 = 2<i>x</i> and <i>x</i> = 20. (Each angle is 70°.)", "type": "mc"}, {"id": "t2m1-7", "sec": "math", "domain": "Algebra", "skill": "Linear equations in two variables", "stem": "Which equation represents the line that has a slope of −3 and passes through the point (1, 5)?", "choices": ["<i>y</i> = −3<i>x</i> + 2", "<i>y</i> = −3<i>x</i> + 5", "<i>y</i> = −3<i>x</i> + 8", "<i>y</i> = 3<i>x</i> + 2"], "answer": 2, "explanation": "Use <i>y</i> = −3<i>x</i> + <i>b</i>. Substitute (1, 5): 5 = −3 + <i>b</i>, so <i>b</i> = 8. The line is <i>y</i> = −3<i>x</i> + 8.", "type": "mc"}, {"id": "t2m1-8", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "stem": "What are the solutions to <i>x</i><sup>2</sup> + 10<i>x</i> + 21 = 0?", "choices": ["−3 and 7", "−3 and −7", "3 and −7", "3 and 7"], "answer": 1, "explanation": "Find two numbers that multiply to 21 and add to 10: 3 and 7. So (<i>x</i> + 3)(<i>x</i> + 7) = 0, giving <i>x</i> = −3 and <i>x</i> = −7.", "type": "mc"}, {"id": "t2m1-9", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "One-variable data: distributions and measures of center and spread", "stem": "What is the range of the data set 12, 5, 19, 8, 26, 14?", "choices": null, "answer": "21", "explanation": "Range = maximum − minimum = 26 − 5 = 21.", "type": "spr"}, {"id": "t2m1-10", "sec": "math", "domain": "Algebra", "skill": "Linear inequalities in one or two variables", "stem": "A student needs an average score of at least 85 on four tests to earn a B. The student scored 78, 88, and 90 on the first three tests. What is the minimum score the student needs on the fourth test?", "choices": null, "answer": "84", "explanation": "An average of at least 85 on 4 tests means a total of at least 4 × 85 = 340. The first three total 78 + 88 + 90 = 256. 340 − 256 = 84.", "type": "spr"}, {"id": "t2m1-11", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear functions", "stem": "An investment of $2,000 earns 3% interest compounded once per year. Which expression gives the value of the investment, in dollars, after <i>t</i> years?", "choices": ["2,000(1.03)<sup><i>t</i></sup>", "2,000(1.3)<sup><i>t</i></sup>", "2,000(0.03)<sup><i>t</i></sup>", "2,000 + 0.03<i>t</i>"], "answer": 0, "explanation": "Each year the value is multiplied by 1 + 0.03 = 1.03, so after <i>t</i> years it is 2,000(1.03)<sup><i>t</i></sup>. Choice D is linear (and adds only a few cents); choice B would be 30% growth.", "type": "mc"}, {"id": "t2m1-12", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "stem": "A triangle has a base of 14 centimeters and a height of 9 centimeters. What is the area, in square centimeters, of the triangle?", "choices": ["23", "31.5", "63", "126"], "answer": 2, "explanation": "Area = (1/2)(base)(height) = (1/2)(14)(9) = 63. Choice D forgets the 1/2.", "type": "mc"}, {"id": "t2m1-13", "sec": "math", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "stem": "<div class=\"eq\"><i>y</i> = 3<i>x</i> − 2<br><i>y</i> = <i>x</i> + 6</div>What is the solution (<i>x</i>, <i>y</i>) to the system of equations above?", "choices": ["(4, 10)", "(8, 14)", "(2, 4)", "(4, 8)"], "answer": 0, "explanation": "Set the expressions equal: 3<i>x</i> − 2 = <i>x</i> + 6, so 2<i>x</i> = 8 and <i>x</i> = 4. Then <i>y</i> = 4 + 6 = 10. Check in the first equation: 3(4) − 2 = 10. ✓", "type": "mc"}, {"id": "t2m1-14", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Probability and conditional probability", "stem": "A spinner is divided into 8 equal sections numbered 1 through 8. If the spinner is spun once, what is the probability that it lands on a number greater than 5?", "choices": ["3/8", "1/2", "3/5", "5/8"], "answer": 0, "explanation": "The numbers greater than 5 are 6, 7, and 8: 3 out of 8 equally likely outcomes, so the probability is 3/8.", "type": "mc"}, {"id": "t2m1-15", "sec": "math", "domain": "Advanced Math", "skill": "Equivalent expressions", "stem": "For <i>x</i> &gt; 0, which expression is equivalent to <i>x</i><sup>3/2</sup>?", "choices": ["√(<i>x</i><sup>3</sup>)", "(3/2)<i>x</i>", "<i>x</i><sup>3</sup>/2", "∛(<i>x</i><sup>2</sup>)"], "answer": 0, "explanation": "A fractional exponent <i>m</i>/<i>n</i> means the <i>n</i>th root of the <i>m</i>th power: <i>x</i><sup>3/2</sup> = √(<i>x</i><sup>3</sup>).", "type": "mc"}, {"id": "t2m1-16", "sec": "math", "domain": "Algebra", "skill": "Linear equations in one variable", "stem": "Renting a kayak costs a flat fee of $18 plus $6 per hour. A family paid a total of $54 to rent one kayak. For how many hours did they rent the kayak?", "choices": null, "answer": "6", "explanation": "18 + 6<i>h</i> = 54, so 6<i>h</i> = 36 and <i>h</i> = 6 hours.", "type": "spr"}, {"id": "t2m1-17", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Two-variable data: models and scatterplots", "stem": "<table class=\"data\"><tr><th><i>x</i></th><td>1</td><td>2</td><td>3</td><td>4</td></tr><tr><th><i>y</i></th><td>7</td><td>10</td><td>13</td><td>16</td></tr></table>Which equation could represent the relationship between <i>x</i> and <i>y</i> shown in the table?", "choices": ["<i>y</i> = 3<i>x</i> + 7", "<i>y</i> = 3<i>x</i> + 4", "<i>y</i> = 4<i>x</i> + 3", "<i>y</i> = <i>x</i> + 6"], "answer": 1, "explanation": "Each time <i>x</i> increases by 1, <i>y</i> increases by 3, so the slope is 3. When <i>x</i> = 1, <i>y</i> = 7, so 7 = 3(1) + <i>b</i> and <i>b</i> = 4: <i>y</i> = 3<i>x</i> + 4. Check <i>x</i> = 4: 3(4) + 4 = 16. ✓", "type": "mc"}, {"id": "t2m1-18", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear functions", "stem": "The function <i>f</i> is defined by <i>f</i>(<i>x</i>) = <i>x</i><sup>2</sup> + 2<i>x</i> − 8. At which points does the graph of <i>y</i> = <i>f</i>(<i>x</i>) cross the <i>x</i>-axis?", "choices": ["(0, −8) only", "(−8, 0) and (1, 0)", "(−4, 0) and (2, 0)", "(4, 0) and (−2, 0)"], "answer": 2, "explanation": "Set <i>f</i>(<i>x</i>) = 0 and factor: (<i>x</i> + 4)(<i>x</i> − 2) = 0, so <i>x</i> = −4 or <i>x</i> = 2. The points are (−4, 0) and (2, 0). Choice A is the <i>y</i>-intercept.", "type": "mc"}, {"id": "t2m1-19", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "stem": "In a right triangle, the two acute angles measure <i>a</i>° and <i>b</i>°. If sin <i>a</i>° = 0.6, what is the value of cos <i>b</i>°?", "choices": ["0.4", "0.6", "0.8", "1.6"], "answer": 1, "explanation": "The acute angles of a right triangle are complementary (<i>a</i> + <i>b</i> = 90). The sine of an angle equals the cosine of its complement, so cos <i>b</i>° = sin <i>a</i>° = 0.6.", "type": "mc"}, {"id": "t2m1-20", "sec": "math", "domain": "Algebra", "skill": "Linear equations in one variable", "stem": "In the equation 2(3<i>x</i> − <i>k</i>) = 6<i>x</i> − 10, <i>k</i> is a constant. If the equation has infinitely many solutions, what is the value of <i>k</i>?", "choices": null, "answer": "5", "explanation": "Distribute: 6<i>x</i> − 2<i>k</i> = 6<i>x</i> − 10. The <i>x</i>-terms already match, so the equation is true for every <i>x</i> exactly when −2<i>k</i> = −10, which means <i>k</i> = 5.", "type": "spr"}, {"id": "t2m1-21", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Evaluating statistical claims: observational studies and experiments", "stem": "A researcher surveyed 50 people working out at one gym on a Saturday morning and found that 80% of them exercise at least four days per week. Which conclusion is best supported by this survey?", "choices": ["Among the 50 people surveyed, 40 reported exercising at least four days per week.", "Going to the gym causes people to exercise at least four days per week.", "About 80% of all gym members in the country exercise at least four days per week.", "About 80% of adults in the city exercise at least four days per week."], "answer": 0, "explanation": "The sample was not chosen at random from a larger population, and people at a gym on a Saturday morning are likely to exercise more than average. So the result can't be generalized to a city, to adults, or to all gyms. The only safe claim is about the people who were actually surveyed.", "type": "mc"}, {"id": "t2m1-22", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "stem": "A cube has a volume of 64 cubic inches. What is the total surface area, in square inches, of the cube?", "choices": ["16", "64", "96", "384"], "answer": 2, "explanation": "Edge length = ∛64 = 4 inches. A cube has 6 square faces, each 4 × 4 = 16, so the surface area is 6 × 16 = 96 square inches.", "type": "mc"}]}, {"minutes": 35, "questions": [{"id": "t2m2-1", "sec": "math", "domain": "Algebra", "skill": "Linear equations in one variable", "stem": "If (2/3)<i>x</i> − 4 = 10, what is the value of <i>x</i>?", "choices": ["9", "14", "21", "28"], "answer": 2, "explanation": "Add 4: (2/3)<i>x</i> = 14. Multiply both sides by 3/2: <i>x</i> = 21.", "type": "mc"}, {"id": "t2m2-2", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Ratios, rates, proportions, and units", "stem": "A rectangular poster measures 3 feet by 2 feet. What is the area of the poster in square inches? (1 foot = 12 inches)", "choices": null, "answer": "864", "explanation": "Convert each side first: 3 ft = 36 in and 2 ft = 24 in. Area = 36 × 24 = 864 square inches. (Note: 1 square foot = 144 square inches, not 12, so 6 ft<sup>2</sup> × 144 = 864.)", "type": "spr"}, {"id": "t2m2-3", "sec": "math", "domain": "Advanced Math", "skill": "Equivalent expressions", "stem": "For <i>x</i> ≠ 3, which expression is equivalent to (<i>x</i><sup>2</sup> − 9)/(<i>x</i> − 3)?", "choices": ["<i>x</i> − 3", "<i>x</i> − 9", "<i>x</i> + 9", "<i>x</i> + 3"], "answer": 3, "explanation": "<i>x</i><sup>2</sup> − 9 is a difference of squares: (<i>x</i> − 3)(<i>x</i> + 3). Cancel the common factor (<i>x</i> − 3) to get <i>x</i> + 3.", "type": "mc"}, {"id": "t2m2-4", "sec": "math", "domain": "Algebra", "skill": "Linear functions", "stem": "A line in the <i>xy</i>-plane passes through the points (−2, 5) and (4, −7). What is the slope of the line?", "choices": null, "answer": "-2", "explanation": "Slope = (−7 − 5)/(4 − (−2)) = −12/6 = −2.", "type": "spr"}, {"id": "t2m2-5", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Percentages", "stem": "After a 15% discount, the price of a pair of shoes is $68. What was the original price?", "choices": ["$57.80", "$78.20", "$80.00", "$83.00"], "answer": 2, "explanation": "After a 15% discount you pay 85% of the original: 0.85<i>p</i> = 68, so <i>p</i> = 68/0.85 = 80. Choice B adds 15% of $68, which is a common mistake.", "type": "mc"}, {"id": "t2m2-6", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "stem": "<div class=\"eq\"><i>x</i><sup>2</sup> + <i>y</i> = 10<br><i>y</i> = <i>x</i> + 4</div>Which of the following is an <i>x</i>-value of a solution to the system of equations above?", "choices": ["−3", "−2", "1", "3"], "answer": 0, "explanation": "Substitute <i>y</i> = <i>x</i> + 4: <i>x</i><sup>2</sup> + <i>x</i> + 4 = 10, so <i>x</i><sup>2</sup> + <i>x</i> − 6 = 0. Factor: (<i>x</i> + 3)(<i>x</i> − 2) = 0, so <i>x</i> = −3 or <i>x</i> = 2. Only −3 is a choice.", "type": "mc"}, {"id": "t2m2-7", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "stem": "A rectangular box has a length of 4 inches, a width of 5 inches, and a volume of 140 cubic inches. What is the height of the box, in inches?", "choices": ["5", "6", "7", "8"], "answer": 2, "explanation": "V = <i>lwh</i>: 140 = 4 × 5 × <i>h</i> = 20<i>h</i>, so <i>h</i> = 7.", "type": "mc"}, {"id": "t2m2-8", "sec": "math", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "stem": "Which system of equations has no solution?", "choices": ["<i>y</i> = 2<i>x</i> + 1 and <i>y</i> = 2<i>x</i> − 3", "<i>y</i> = 2<i>x</i> + 1 and <i>y</i> = −2<i>x</i> + 1", "<i>y</i> = <i>x</i> and <i>y</i> = 2<i>x</i>", "<i>y</i> = 3<i>x</i> + 1 and 2<i>y</i> = 6<i>x</i> + 2"], "answer": 0, "explanation": "Two lines with the same slope and different <i>y</i>-intercepts are parallel and never meet. In A both lines have slope 2 but intercepts 1 and −3. B and C have different slopes (one solution each). In D, 2<i>y</i> = 6<i>x</i> + 2 simplifies to <i>y</i> = 3<i>x</i> + 1, the same line (infinitely many solutions).", "type": "mc"}, {"id": "t2m2-9", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "One-variable data: distributions and measures of center and spread", "stem": "The mean of a list of 5 numbers is 12. When a sixth number is added to the list, the mean of the 6 numbers is 13. What is the sixth number?", "choices": null, "answer": "18", "explanation": "The 5 numbers sum to 5 × 12 = 60. The 6 numbers sum to 6 × 13 = 78. The sixth number is 78 − 60 = 18.", "type": "spr"}, {"id": "t2m2-10", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear functions", "stem": "The function <i>f</i> is defined by <i>f</i>(<i>x</i>) = (<i>x</i> − 2)(<i>x</i> + 5). What is the <i>y</i>-intercept of the graph of <i>y</i> = <i>f</i>(<i>x</i>) in the <i>xy</i>-plane?", "choices": ["(0, −3)", "(0, 3)", "(0, −10)", "(0, 10)"], "answer": 2, "explanation": "The <i>y</i>-intercept occurs at <i>x</i> = 0: <i>f</i>(0) = (0 − 2)(0 + 5) = −10, so the point is (0, −10).", "type": "mc"}, {"id": "t2m2-11", "sec": "math", "domain": "Algebra", "skill": "Linear equations in two variables", "stem": "What is the <i>x</i>-coordinate of the <i>x</i>-intercept of the graph of 3<i>x</i> + 4<i>y</i> = 24?", "choices": ["4", "6", "8", "24"], "answer": 2, "explanation": "The <i>x</i>-intercept is where <i>y</i> = 0: 3<i>x</i> = 24, so <i>x</i> = 8. (Choice B, 6, is the <i>y</i>-intercept.)", "type": "mc"}, {"id": "t2m2-12", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "stem": "If 2<sup><i>x</i> + 3</sup> = 32, what is the value of <i>x</i>?", "choices": null, "answer": "2", "explanation": "Write 32 as a power of 2: 32 = 2<sup>5</sup>. So <i>x</i> + 3 = 5 and <i>x</i> = 2.", "type": "spr"}, {"id": "t2m2-13", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "One-variable data: distributions and measures of center and spread", "stem": "<p>Data set A: 10, 10, 10, 10, 10<br>Data set B: 5, 8, 10, 12, 15</p>Which statement about the two data sets is true?", "choices": ["The data sets have the same mean, and data set B has a larger standard deviation.", "The data sets have the same mean, and data set A has a larger standard deviation.", "The data sets have the same mean and the same standard deviation.", "Data set B has a larger mean and a larger standard deviation."], "answer": 0, "explanation": "Both sets sum to 50, so both means are 10. Set A has no spread at all (standard deviation 0), while the values in set B are spread out around 10, so B has the larger standard deviation.", "type": "mc"}, {"id": "t2m2-14", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "stem": "In a right triangle, the hypotenuse has length 10 and one of the acute angles measures 30°. What is the length of the shorter leg?", "choices": ["5", "20", "5√3", "10√3"], "answer": 0, "explanation": "In a 30°-60°-90° triangle, the side lengths are in the ratio 1 : √3 : 2 (short leg : long leg : hypotenuse). The short leg is half the hypotenuse: 10/2 = 5. (Or: short leg = 10 sin 30° = 10 × 0.5 = 5.)", "type": "mc"}, {"id": "t2m2-15", "sec": "math", "domain": "Algebra", "skill": "Linear equations in one variable", "stem": "Gym A charges a $35 sign-up fee plus $22 per month. Gym B charges a $70 sign-up fee plus $15 per month. After how many months will the total cost be the same at both gyms?", "choices": null, "answer": "5", "explanation": "Set the totals equal: 35 + 22<i>m</i> = 70 + 15<i>m</i>. Subtract 15<i>m</i> and 35: 7<i>m</i> = 35, so <i>m</i> = 5. Check: Gym A = 35 + 110 = $145; Gym B = 70 + 75 = $145. ✓", "type": "spr"}, {"id": "t2m2-16", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear functions", "stem": "The function <i>f</i> is defined by <i>f</i>(<i>x</i>) = <i>a</i>(<i>x</i> − 1)(<i>x</i> − 7), where <i>a</i> is a negative constant. What is the <i>x</i>-coordinate of the vertex of the graph of <i>y</i> = <i>f</i>(<i>x</i>)?", "choices": ["1", "3", "4", "7"], "answer": 2, "explanation": "A parabola is symmetric, so the vertex lies halfway between the <i>x</i>-intercepts 1 and 7: (1 + 7)/2 = 4. The value of <i>a</i> doesn't change this.", "type": "mc"}, {"id": "t2m2-17", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Probability and conditional probability", "stem": "In a group of 80 students, 30 play a sport, 25 are in the band, and 10 both play a sport and are in the band. If a student in the band is chosen at random, what is the probability that the student also plays a sport?", "choices": ["1/8", "1/3", "2/5", "2/3"], "answer": 2, "explanation": "The condition \"a student in the band\" means the 25 band members are the whole group to choose from. 10 of them play a sport: 10/25 = 2/5. Choice A (10/80) uses all 80 students instead.", "type": "mc"}, {"id": "t2m2-18", "sec": "math", "domain": "Advanced Math", "skill": "Equivalent expressions", "stem": "Which expression is equivalent to (3<i>x</i> − 1)<sup>2</sup>?", "choices": ["9<i>x</i><sup>2</sup> − 1", "9<i>x</i><sup>2</sup> + 1", "9<i>x</i><sup>2</sup> − 6<i>x</i> + 1", "9<i>x</i><sup>2</sup> − 3<i>x</i> + 1"], "answer": 2, "explanation": "(3<i>x</i> − 1)(3<i>x</i> − 1) = 9<i>x</i><sup>2</sup> − 3<i>x</i> − 3<i>x</i> + 1 = 9<i>x</i><sup>2</sup> − 6<i>x</i> + 1. Squaring a binomial always produces a middle term; choice A forgets it.", "type": "mc"}, {"id": "t2m2-19", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "stem": "Two similar triangles have corresponding side lengths in the ratio 2 : 5. The area of the smaller triangle is 12 square units. What is the area, in square units, of the larger triangle?", "choices": null, "answer": "75", "explanation": "When lengths scale by a factor of 5/2, areas scale by the square of that factor, (5/2)<sup>2</sup> = 25/4. Larger area = 12 × 25/4 = 75. (Multiplying by just 5/2 gives 30, a common trap.)", "type": "spr"}, {"id": "t2m2-20", "sec": "math", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "stem": "<div class=\"eq\">3<i>a</i> + 2<i>b</i> = 17<br><i>a</i> − 2<i>b</i> = −1</div>If (<i>a</i>, <i>b</i>) is the solution to the system of equations above, what is the value of <i>a</i> + <i>b</i>?", "choices": null, "answer": "13/2", "explanation": "Add the equations to eliminate <i>b</i>: 4<i>a</i> = 16, so <i>a</i> = 4. Substitute: 4 − 2<i>b</i> = −1, so <i>b</i> = 2.5. Then <i>a</i> + <i>b</i> = 6.5 (entered as 13/2 or 6.5).", "type": "spr"}, {"id": "t2m2-21", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear functions", "stem": "A quantity starts at 500 and increases by 40% every 2 years. Which function gives the quantity, <i>Q</i>(<i>t</i>), after <i>t</i> years?", "choices": ["<i>Q</i>(<i>t</i>) = 500(1.4)<sup>2<i>t</i></sup>", "<i>Q</i>(<i>t</i>) = 500(1.4)<sup><i>t</i>/2</sup>", "<i>Q</i>(<i>t</i>) = 500(0.4)<sup><i>t</i>/2</sup>", "<i>Q</i>(<i>t</i>) = 500(1.2)<sup><i>t</i></sup>"], "answer": 1, "explanation": "A 40% increase means multiplying by 1.4. That happens once every 2 years, so after <i>t</i> years it has happened <i>t</i>/2 times: <i>Q</i>(<i>t</i>) = 500(1.4)<sup><i>t</i>/2</sup>. Check: <i>Q</i>(2) = 700 and <i>Q</i>(4) = 980. Choice D gives <i>Q</i>(2) = 720, which is not a 40% increase.", "type": "mc"}, {"id": "t2m2-22", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Percentages", "stem": "The number of members in a club increased from 40 to 52. By what percent did the number of members increase?", "choices": ["12%", "23%", "30%", "52%"], "answer": 2, "explanation": "Percent change = (new − old)/old × 100 = (52 − 40)/40 × 100 = 12/40 × 100 = 30%. Choice A gives the raw change (12), not the percent change.", "type": "mc"}]}]}]}], "practiceExtra": [{"sec": "rw", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "The hikers were <span class=\"blank\">______</span> after the long climb; several of them sat down and fell asleep as soon as they reached the camp.", "stem": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["energized", "lost", "impatient", "exhausted"], "explanation": "Falling asleep immediately after a long climb shows extreme tiredness: <b>exhausted</b>.", "type": "mc", "answer": 3, "id": "prw-1"}, {"sec": "rw", "domain": "Craft and Structure", "skill": "Text Structure and Purpose", "passage": "Coral reefs cover less than 1 percent of the ocean floor. <u>Yet they are home to roughly a quarter of all known marine species.</u>", "stem": "Which choice best describes the function of the underlined sentence?", "choices": ["It presents a fact that contrasts with what the first sentence might lead a reader to expect.", "It restates the first sentence in different words.", "It explains what causes the fact described in the first sentence.", "It gives an example that illustrates the first sentence."], "explanation": "\"Yet\" signals contrast: reefs are tiny in area but hold a huge share of species.", "type": "mc", "answer": 0, "id": "prw-2"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Inferences", "passage": "A gardener noticed that tomato plants on the sunny side of her yard produced about twice as much fruit as identical plants on the shady side, even though she watered and fertilized all of the plants the same way and the soil on both sides was the same. This suggests that <span class=\"blank\">______</span>", "stem": "Which choice most logically completes the text?", "choices": ["fertilizer has no effect on tomato plants.", "the amount of sunlight likely affected how much fruit the plants produced.", "tomato plants need less water in shady areas.", "the shady side of the yard had better soil."], "explanation": "Water, fertilizer, and soil were the same, so sunlight is the main difference.", "type": "mc", "answer": 1, "id": "prw-3"}, {"sec": "rw", "domain": "Information and Ideas", "skill": "Command of Evidence: Textual", "passage": "A student claims that the new bike lanes a town added to some of its streets made cycling on those streets safer.", "stem": "Which finding, if true, would most directly support the student's claim?", "choices": ["The number of bicycle accidents on streets with new lanes fell by 40 percent, while it stayed about the same on streets without new lanes.", "Car traffic in the town increased during the same period.", "More people in the town bought bicycles after the lanes were added.", "The new bike lanes were painted bright green."], "explanation": "Safety is measured by accidents, and comparing streets with and without lanes ties the drop to the lanes.", "type": "mc", "answer": 0, "id": "prw-4"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Boundaries", "passage": "The summer camp offers three main <span class=\"blank\">______</span> archery, canoeing, and rock climbing.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["activities, which", "activities:", "activities, such as:", "activities;"], "explanation": "A colon introduces a list after a complete clause. \"Such as\" should not be followed by a colon.", "type": "mc", "answer": 1, "id": "prw-5"}, {"sec": "rw", "domain": "Standard English Conventions", "skill": "Form, Structure, and Sense", "passage": "The list of supplies for the camping trip <span class=\"blank\">______</span> posted on the club's website.", "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["have been", "are", "is", "were"], "explanation": "The subject is the singular \"list,\" not \"supplies.\"", "type": "mc", "answer": 2, "id": "prw-6"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "The bakery's bread sold out by 9 a.m. every day. <span class=\"blank\">______</span> the owner decided to double the size of each morning's batch.", "stem": "Which choice completes the text with the most logical transition?", "choices": ["Similarly,", "However,", "For example,", "Consequently,"], "explanation": "Doubling the batch is a result of the bread selling out early.", "type": "mc", "answer": 3, "id": "prw-7"}, {"sec": "rw", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "<p>While researching a topic, a student has taken the following notes:</p><ul><li>Venus is the second planet from the Sun.</li><li>One rotation of Venus on its axis (a day) takes about 243 Earth days.</li><li>One orbit of Venus around the Sun (a year) takes about 225 Earth days.</li></ul>", "stem": "The student wants to emphasize a surprising fact about the length of a day on Venus. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Venus orbits the Sun once every 225 Earth days.", "Venus is the second planet from the Sun.", "A year on Venus lasts about 225 Earth days.", "A single rotation of Venus takes about 243 Earth days, which is longer than its year of about 225 Earth days."], "explanation": "The surprising fact is that a day on Venus is longer than its year. Only choice D compares them.", "type": "mc", "answer": 3, "id": "prw-8"}, {"id": "pm-1", "sec": "math", "domain": "Algebra", "skill": "Linear equations in one variable", "stem": "If 7 − 2<i>x</i> = −9, what is the value of <i>x</i>?", "choices": null, "answer": "8", "explanation": "Subtract 7: −2<i>x</i> = −16. Divide by −2: <i>x</i> = 8.", "type": "spr"}, {"id": "pm-2", "sec": "math", "domain": "Algebra", "skill": "Linear inequalities in one or two variables", "stem": "Which point (<i>x</i>, <i>y</i>) is a solution to the inequality <i>y</i> &gt; 2<i>x</i> − 1?", "choices": ["(3, 4)", "(2, 3)", "(1, 1)", "(0, 0)"], "answer": 3, "explanation": "Test each point. (0, 0): 0 &gt; −1 ✓. (2, 3): 3 &gt; 3 ✗ (equal is not greater). (1, 1): 1 &gt; 1 ✗. (3, 4): 4 &gt; 5 ✗.", "type": "mc"}, {"id": "pm-3", "sec": "math", "domain": "Algebra", "skill": "Linear equations in two variables", "stem": "What is the slope of the line 6<i>x</i> + 2<i>y</i> = 7?", "choices": ["−3", "−1/3", "3", "7/2"], "answer": 0, "explanation": "Solve for <i>y</i>: 2<i>y</i> = −6<i>x</i> + 7, so <i>y</i> = −3<i>x</i> + 3.5. The slope is −3.", "type": "mc"}, {"id": "pm-4", "sec": "math", "domain": "Advanced Math", "skill": "Equivalent expressions", "stem": "Which expression is equivalent to <i>x</i><sup>2</sup> − 16?", "choices": ["(<i>x</i> − 8)(<i>x</i> + 8)", "(<i>x</i> − 4)(<i>x</i> + 4)", "(<i>x</i> − 4)<sup>2</sup>", "(<i>x</i> + 4)<sup>2</sup>"], "answer": 1, "explanation": "This is a difference of squares, <i>a</i><sup>2</sup> − <i>b</i><sup>2</sup> = (<i>a</i> − <i>b</i>)(<i>a</i> + <i>b</i>), with <i>a</i> = <i>x</i> and <i>b</i> = 4.", "type": "mc"}, {"id": "pm-5", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear functions", "stem": "If <i>f</i>(<i>x</i>) = 3<sup><i>x</i></sup>, what is the value of <i>f</i>(4)?", "choices": null, "answer": "81", "explanation": "3<sup>4</sup> = 3 × 3 × 3 × 3 = 81.", "type": "spr"}, {"id": "pm-6", "sec": "math", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "stem": "If √(2<i>x</i> + 5) = 5, what is the value of <i>x</i>?", "choices": null, "answer": "10", "explanation": "Square both sides: 2<i>x</i> + 5 = 25. Then 2<i>x</i> = 20, so <i>x</i> = 10. Check: √25 = 5. ✓", "type": "spr"}, {"id": "pm-7", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Percentages", "stem": "40% of what number is 18?", "choices": null, "answer": "45", "explanation": "0.40<i>n</i> = 18, so <i>n</i> = 18/0.40 = 45.", "type": "spr"}, {"id": "pm-8", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Ratios, rates, proportions, and units", "stem": "A robot moves at a constant speed of 1.5 meters per second. How many meters does it travel in 2 minutes?", "choices": ["3", "90", "180", "300"], "answer": 2, "explanation": "Convert minutes to seconds first: 2 minutes = 120 seconds. Distance = 1.5 × 120 = 180 meters. Choice A forgets to convert.", "type": "mc"}, {"id": "pm-9", "sec": "math", "domain": "Problem-Solving and Data Analysis", "skill": "Probability and conditional probability", "stem": "Two fair coins are flipped. What is the probability that both land heads?", "choices": ["1/4", "1/3", "1/2", "3/4"], "answer": 0, "explanation": "The four equally likely outcomes are HH, HT, TH, TT. Only HH works: 1/4.", "type": "mc"}, {"id": "pm-10", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "stem": "An isosceles triangle has two base angles that each measure 50°. What is the measure, in degrees, of the third angle?", "choices": null, "answer": "80", "explanation": "180 − 50 − 50 = 80.", "type": "spr"}, {"id": "pm-11", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "stem": "A right triangle has legs of length 5 and 12. What is the tangent of the angle opposite the side of length 5?", "choices": ["5/13", "5/12", "12/13", "12/5"], "answer": 1, "explanation": "tan = opposite/adjacent. The side opposite the angle is 5, and the other leg (12) is adjacent: tan = 5/12.", "type": "mc"}, {"id": "pm-12", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "stem": "A square has a diagonal of length 8√2. What is the area of the square?", "choices": ["16", "32", "64", "128"], "answer": 2, "explanation": "A square's diagonal is side × √2, so the side is 8. Area = 8<sup>2</sup> = 64.", "type": "mc"}, {"id": "pm-13", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Circles", "stem": "A circle in the <i>xy</i>-plane has the equation (<i>x</i> − 2)<sup>2</sup> + (<i>y</i> + 5)<sup>2</sup> = 49. What is the radius of the circle?", "choices": null, "answer": "7", "explanation": "The standard form of a circle is (<i>x</i> − <i>h</i>)<sup>2</sup> + (<i>y</i> − <i>k</i>)<sup>2</sup> = <i>r</i><sup>2</sup>, with center (<i>h</i>, <i>k</i>). Here <i>r</i><sup>2</sup> = 49, so <i>r</i> = 7. (The center is (2, −5).) Don't enter 49; that is <i>r</i><sup>2</sup>.", "type": "spr"}, {"id": "pm-14", "sec": "math", "domain": "Geometry and Trigonometry", "skill": "Circles", "stem": "A circle has a radius of 6 centimeters. What is the length, in centimeters, of an arc of the circle that is intercepted by a central angle measuring 60°?", "choices": ["6π", "12π", "π", "2π"], "answer": 3, "explanation": "An arc is the same fraction of the circumference as its central angle is of 360°: 60/360 = 1/6. The circumference is 2π(6) = 12π, so the arc length is 12π/6 = 2π.", "type": "mc"}]};
